let mtVenueSurcharge = 0;

function getReliableMtTotal() {
  const parseCur = v => { if (typeof v === 'number') return v; const c = String(v || '').replace(/[^\d.-]/g, ''); return parseFloat(c) || 0; };

  // 0. Absolute Highest Priority: What the user actually sees on screen
  // Skip this when in any modify mode — we need a fresh calculation, not a stale DOM value.
  const _inModifyMode = (typeof mtModifyMode !== 'undefined' && mtModifyMode) || (typeof resdModifyMode !== 'undefined' && resdModifyMode);
  if (!_inModifyMode) {
    const totalEl = document.getElementById('mt-mode-total-price');
    if (totalEl && totalEl.textContent) {
      const domTotal = parseCur(totalEl.textContent);
      if (domTotal > 0) return domTotal;
    }
  }

  const pax = parseInt(mtPax) || 1;
  let origin = 'custom';
  let cache = activeMeetingResCache;

  // Determine if we are in Meeting Room or Reservation Details
  if (typeof activeResDetailId !== 'undefined' && activeResDetailId) {
    if (typeof getResdOrigin === 'function') origin = getResdOrigin();
    cache = RESERVATIONS.find(r => r.id === activeResDetailId) || null;
  } else if (activeMeetingResCache) {
    origin = getMtOrigin(); // Uses packageOrigin → pricingMode → packageCategory fallback chain
  }

  // 1. Modifying Mode: Real-time calculation is required
  if ((typeof mtModifyMode !== 'undefined' && mtModifyMode) || (typeof resdModifyMode !== 'undefined' && resdModifyMode)) {
    if (origin === 'custom') {
      const base = mtCustomPkgItems.reduce((sum, item) => sum + getDynamicPrice(item, pax), 0);
      return base + (mtVenueSurcharge || 0);
    }
    if (origin === 'dynamically set') {
      // Use pricePerHead, _pricePerPax, or derive rate from old amount / old pax
      const rate = cache?.pricePerHead ? parseCur(cache.pricePerHead) : (parseCur(cache?._pricePerPax) || (parseCur(cache?.amount) / (parseInt(cache?.pax) || pax)) || 500);
      return (rate * pax) + (mtVenueSurcharge || 0);
    }
    if (origin === 'majorly set') {
      return parseCur(cache?.amount);
    }
  }

  // 2. Normal Mode: Stored amount is the source of truth
  let total = 0;
  if (cache && cache.amount) total = parseCur(cache.amount);
  else if (cache && cache.price) total = parseCur(cache.price);

  // 3. Fallback to RESERVATIONS array
  if (total === 0 && typeof activeMeeting !== 'undefined' && activeMeeting) {
    const res = RESERVATIONS.find(r => r.id === activeMeeting.reservationId);
    if (res && res.amount) total = parseCur(res.amount);
  }

  // 4. Sanity Check removed — it was multiplying valid stored amounts incorrectly.

  // 5. Final Fallback: calculate from scratch if total is still 0
  if (total === 0) {
    if (origin === 'custom' && typeof mtCustomPkgItems !== 'undefined') {
      const base = mtCustomPkgItems.reduce((sum, item) => sum + getDynamicPrice(item, pax), 0);
      total = base + (mtVenueSurcharge || 0);
    } else if (origin === 'dynamically set') {
      const rate = parseCur(cache?.pricePerHead) || parseCur(cache?._pricePerPax) || (parseCur(cache?.amount) / (parseInt(cache?.pax) || pax)) || 500;
      total = (rate * pax) + (mtVenueSurcharge || 0);
    }
  }

  return total;
}

// Keep calculateMtPrice as a proxy to avoid breaking other calls
function calculateMtPrice() {
  return getReliableMtTotal();
}

