// ===== AUTH GUARD =====
async function checkAuth() {
  const logged = sessionStorage.getItem('halden_admin');
  if (!logged) { window.location.href = 'index.html'; return; }
  
  // Harden auth: verify the Supabase token hasn't been overwritten by a customer tab
  const { data: { session } } = await window.supabaseClient.auth.getSession();
  if (!session) {
    adminLogout();
    return;
  }
  
  // Check if current Supabase session is genuinely an admin
  const role = session.user.user_metadata?.role;
  if (role !== 'admin') {
    alert("Session mismatch: You logged into a non-admin account in another tab. Please log in as Admin again.");
    adminLogout();
    return;
  }

  try {
    const u = JSON.parse(logged);
    document.getElementById('admin-name').textContent = u.name || 'Administrator';
  } catch (e) { }
}
function adminLogout() {
  sessionStorage.removeItem('halden_admin');
  localStorage.removeItem('halden_logged_in');
  localStorage.removeItem('currentUser');
  localStorage.removeItem('currentUserId');
  localStorage.removeItem('session_start');
  localStorage.removeItem('sb-nukbdmyqizrnkmbusdtm-auth-token');
  localStorage.removeItem('halden_auto_open_dash');
  localStorage.setItem('halden_user_type', '');

  if (window.supabaseClient && window.supabaseClient.auth) {
    window.supabaseClient.auth.signOut().catch(() => { }).finally(() => {
      window.location.href = 'index.html';
    });
  } else {
    window.location.href = 'index.html';
  }
}
checkAuth();

