// EIM_ASSETS is declared at the top of the file (near line 572)
let lastGeneratedManifest = null;
let currentAllocMode = false;

// Initialize tracking mode for each asset (lightweight — no sub-item generation for batch rows)
function initializeEquipmentTracking(assets) {
  assets.forEach((a, idx) => {
    // Ensure id is always a string
    if (!a.id) a.id = 'EQ-' + String(idx + 1).padStart(4, '0');
    a.id = String(a.id);

    // Normalize status to Title Case
    if (a.status) {
      const s = a.status.toLowerCase();
      if (s === 'available') a.status = 'Available';
      else if (s === 'active') a.status = 'Active';
      else if (s === 'in use' || s === 'in_use') a.status = 'In Use';
      else if (s === 'under repair' || s === 'under_repair') a.status = 'Under Repair';
      else if (s === 'retired') a.status = 'Retired';
    } else {
      a.status = 'Available';
    }

    // Normalize condition to Title Case
    if (a.condition) {
      const c = a.condition.toLowerCase();
      if (c === 'excellent') a.condition = 'Excellent';
      else if (c === 'good') a.condition = 'Good';
      else if (c === 'fair') a.condition = 'Fair';
      else if (c === 'poor') a.condition = 'Poor';
      else if (c === 'damaged') a.condition = 'Damaged';
    } else {
      a.condition = 'Good';
    }

    // Set tracking mode
    if ((a.name || '').toLowerCase().includes('photo booth')) {
      a.trackingMode = 'individual';
    } else {
      a.trackingMode = a.trackingMode || 'batch';
    }

    // Set a batch tracking ID if missing
    if (a.trackingMode === 'batch' && !a.batchTrackingId) {
      const pfx = (a.category || 'EQ').substring(0, 3).toUpperCase().replace(/[^A-Z]/g, '') || 'EQ';
      a.batchTrackingId = `BAT-${pfx}-${a.id}`;
    }

    // For batch items: create a minimal items array using just quantity (no heavy loop)
    if (a.trackingMode === 'batch' && (!a.items || a.items.length === 0)) {
      const qty = Math.min(parseInt(a.quantity) || 0, 100);
      a.items = Array.from({ length: qty }, (_, i) => ({
        subId: `${a.id}-${String(i + 1).padStart(2, '0')}`,
        condition: a.condition,
        status: a.status
      }));
    }
  });
  return assets;
}

// ===== SUPABASE EQUIPMENT LOADER FOR ADMIN =====
async function loadEIMFromSupabase() {
  try {
    const sb = window.supabaseClient;
    if (!sb) {
      console.warn('[EIM Loader] No supabaseClient on window — using hardcoded fallback.');
      EIM_ASSETS = initializeEquipmentTracking([...EIM_ASSETS_HARDCODED]);
      if (typeof renderEIMTable === 'function') renderEIMTable();
      return;
    }

    console.log('[EIM Loader] Fetching equipment_inventory from Supabase…');

    const { data: rows, error } = await sb
      .from('equipment_inventory')
      .select('id, asset_id, name, category, type, total_qty, available_qty, status, condition, value, notes, description, is_batch, batch_id, purchase_date, price, allocation_type, pricing_type, supplier, source_location, good_qty, maintenance_qty')
      .neq('status', 'disposed');

    if (error) {
      console.error('[EIM Loader] Supabase error:', error.message, error);
      EIM_ASSETS = initializeEquipmentTracking([...EIM_ASSETS_HARDCODED]);
      if (typeof renderEIMTable === 'function') renderEIMTable();
      return;
    }

    console.log('[EIM Loader] Rows received:', rows ? rows.length : 'null', rows);

    if (!rows || rows.length === 0) {
      console.warn('[EIM Loader] Zero rows returned — using hardcoded fallback.');
      EIM_ASSETS = initializeEquipmentTracking([...EIM_ASSETS_HARDCODED]);
      if (typeof renderEIMTable === 'function') renderEIMTable();
      return;
    }

    const mapped = rows.map((row, idx) => ({
      id: row.asset_id || `EQ-${String(idx + 1).padStart(4, '0')}`,
      supabaseId: row.id,
      name: String(row.name || 'Unnamed'),
      category: String(row.category || 'Uncategorized'),
      type: String(row.type || 'General'),
      quantity: parseInt(row.total_qty) || 1,
      availableQty: row.available_qty != null ? parseInt(row.available_qty) : (parseInt(row.total_qty) || 1),
      good_qty: row.good_qty != null ? parseInt(row.good_qty) : (row.available_qty != null ? parseInt(row.available_qty) : (parseInt(row.total_qty) || 1)),
      maintenance_qty: parseInt(row.maintenance_qty) || 0,
      unitType: 'pcs',
      condition: String(row.condition || 'Good'),
      status: String(row.status || 'available'),
      unitCost: parseFloat(row.price) || parseFloat(row.value) || 0,
      supplier: row.supplier || null,
      sourceLocation: row.source_location || null,
      trackingMode: row.is_batch ? 'batch' : 'individual',
      batchTrackingId: row.batch_id || null,
      notes: String(row.description || row.notes || ''),
      addedDate: row.purchase_date || new Date().toISOString().split('T')[0],
      allocationRule: row.allocation_type || 'none',
      pricingRule: row.pricing_type || 'per_unit',
      items: []
    }));

    EIM_ASSETS = initializeEquipmentTracking(mapped);

    console.log(`[EIM Loader] ✅ ${EIM_ASSETS.length} items loaded. Rendering table…`);

    if (typeof renderEIMTable === 'function') renderEIMTable();
    if (typeof renderDashboard === 'function') renderDashboard();

  } catch (err) {
    console.error('[EIM Loader] Unexpected crash:', err);
    EIM_ASSETS = initializeEquipmentTracking([...EIM_ASSETS_HARDCODED]);
    if (typeof renderEIMTable === 'function') renderEIMTable();
    if (typeof renderDashboard === 'function') renderDashboard();
  }
  
  // Now that EIM_ASSETS is guaranteed to be populated, we can safely check/restore the routine session
  if (typeof checkAndExpireSession === 'function') checkAndExpireSession();
  if (typeof getRcSession === 'function') {
    const ses = getRcSession();
    if (ses && activeRoutineCheck && typeof startSessionTimer === 'function') startSessionTimer();
  }
}

// Auto-run: wait 1.5s for Supabase SDK to be fully ready before fetching
setTimeout(loadEIMFromSupabase, 1500);
window.loadEIMFromSupabase = loadEIMFromSupabase;

