// ===== RENDER EIM STATS =====
function renderEIMStats() {
  const total = EIM_ASSETS.length;
  
  let active = 0;
  let repair = 0;
  
  EIM_ASSETS.forEach(a => {
    active += parseInt(a.good_qty) || 0;
    repair += parseInt(a.maintenance_qty) || 0;
  });

  const value = EIM_ASSETS.reduce((sum, a) => {
    const cost = parseFloat(a.unitCost) || 0;
    const qty = parseFloat(a.quantity) || 0;
    return sum + (cost * qty);
  }, 0);

  const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
  set('eim-stat-total', total);
  set('eim-stat-active', active);
  set('eim-stat-repair', repair);
  set('eim-stat-value', '₱' + value.toLocaleString());
}

// ===== QR CODE HELPER FUNCTIONS =====
function shouldHaveIndividualQR(category) {
  const individualQRCategories = ['Furniture', 'AV & Lighting', 'Catering Equipment'];
  return individualQRCategories.includes(category);
}

// Store current QR data globally
let currentQRData = null;

function showEquipmentQR(assetId, subId) {
  const a = EIM_ASSETS.find(x => x.id === assetId);
  if (!a) { alert('Equipment not found.'); return; }

  const isIndividual = !!subId;
  const displayId = subId || assetId;

  // Smart URL payload
  let baseUrl = window.location.origin;
  if (window.location.protocol === 'file:') {
    baseUrl = window.location.href.split('/admin.html')[0];
  }
  const payload = baseUrl + '/scan.html?eq=' + encodeURIComponent(displayId);

  const title = isIndividual ? 'Individual Equipment QR Code' : 'Batch Equipment QR Code';
  const subtitle = isIndividual ? 'Scan to identify this individual unit' : 'Scan to identify this equipment batch';

  document.getElementById('qrModalTitle').textContent = title;
  document.getElementById('qrModalSubtitle').textContent = subtitle;
  document.getElementById('qrLabelId').textContent = displayId;
  document.getElementById('qrLabelName').textContent = a.name + (isIndividual ? ' — Individual Unit' : ' — Batch');

  const rows = isIndividual ? [
    ['Asset ID', displayId, true],
    ['Batch ID', assetId, false],
    ['Equipment', a.name, false],
    ['Category', a.category, false],
    ['Type', a.type, false],
    ['Tracking Mode', 'Individual', false]
  ] : [
    ['Batch ID', assetId, true],
    ['Equipment', a.name, false],
    ['Category', a.category, false],
    ['Type', a.type, false],
    ['Tracking Mode', 'Batch', false]
  ];

  document.getElementById('qrModalMeta').innerHTML = rows.map(([k, v, accent]) =>
    `<div style="display:flex; justify-content:space-between; font-size:11px;"><span style="color:var(--text-dim);">${k}</span><span style="color:${accent ? 'var(--gold)' : 'var(--text)'}; font-weight:500;">${v}</span></div>`
  ).join('');

  const qrContainer = document.getElementById('qrcode');
  qrContainer.innerHTML = '';
  // Make the QR code clickable on PC to bypass scanning
  qrContainer.style.cursor = 'pointer';
  qrContainer.title = 'Click to open scanner page';
  qrContainer.onclick = function() { window.open(payload, '_blank'); };

  const showModal = () => {
    const modal = document.getElementById('qrModal');
    const modalContent = document.getElementById('qrModalContent');
    if (modal) { modal.style.display = 'flex'; modal.classList.add('on'); }
    if (modalContent) modalContent.classList.add('open');
    document.body.style.overflow = 'hidden';
  };

  if (typeof QRCode !== 'undefined') {
    try {
      new QRCode(qrContainer, {
        text: payload,
        width: 200,
        height: 200,
        colorDark: '#111111',
        colorLight: '#ffffff',
        correctLevel: QRCode.CorrectLevel.L
      });
      showModal();
    } catch (error) {
      console.error('QR generation error:', error);
      drawFallbackCanvas(qrContainer, payload);
      showModal();
    }
  } else {
    drawFallbackCanvas(qrContainer, payload);
    showModal();
  }
}

function drawFallbackCanvas(container, text) {
  const canvas = document.createElement('canvas');
  canvas.width = 200;
  canvas.height = 200;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#fff';
  ctx.fillRect(0, 0, 200, 200);
  ctx.fillStyle = '#111';
  ctx.font = 'bold 11px monospace';
  ctx.textAlign = 'center';
  ctx.fillText('QR (Library Unavailable)', 100, 95);
  ctx.font = '10px monospace';
  ctx.fillText(text, 100, 115);
  container.appendChild(canvas);
}


function closeQRModal() {
  const modal = document.getElementById('qrModal');
  const modalContent = document.getElementById('qrModalContent');
  if (!modal || !modalContent) return;
  modal.classList.remove('on');
  modalContent.classList.remove('open');
  setTimeout(() => {
    const m = document.getElementById('qrModal');
    if (m) m.style.display = 'none';
  }, 300);
  document.body.style.overflow = '';
}

function closeQRModalOutside(e) {
  if (e.target === document.getElementById('qrModal')) closeQRModal();
}

// Fallback QR Code Generator
function generateFallbackQR(assetId, assetName, category, type, trackingMode, batchId = null, subId = null, isIndividual = false) {
  console.log('Fallback QR generator called with:', {
    assetId, assetName, category, type, trackingMode, batchId, subId, isIndividual
  });

  // Check if modal elements exist
  const modal = document.getElementById('qrModal');
  const modalContent = document.getElementById('qrModalContent');
  console.log('Modal elements:', { modal: !!modal, modalContent: !!modalContent });

  if (!modal || !modalContent) {
    console.error('Modal elements not found!');
    alert('QR modal not found. Please refresh the page.');
    return;
  }

  currentQRData = {
    id: subId || assetId,
    name: assetName,
    category: category,
    type: type,
    trackingMode: trackingMode,
    batchId: batchId,
    subId: subId,
    isIndividual: isIndividual
  };

  // Smart URL payload
  let baseUrl = window.location.origin;
  if (window.location.protocol === 'file:') {
    baseUrl = window.location.href.split('/admin.html')[0];
  }
  const payload = baseUrl + '/scan.html?eq=' + encodeURIComponent(subId || assetId);

  const title = isIndividual ? 'Individual Equipment QR Code' : 'Batch Equipment QR Code';
  const subtitle = isIndividual ? 'Scan to identify this individual equipment item' : 'Scan to identify this equipment batch';

  document.getElementById('qrModalTitle').textContent = title;
  document.getElementById('qrModalSubtitle').textContent = subtitle;
  document.getElementById('qrLabelId').textContent = subId || assetId;
  document.getElementById('qrLabelName').textContent = assetName + (isIndividual ? ' — Individual Unit' : ' — Batch');

  // Meta information
  const rows = isIndividual ? [
    ['Asset ID', subId, true],
    ['Batch ID', batchId || '—', false],
    ['Equipment', assetName, false],
    ['Category', category, false],
    ['Type', type, false],
    ['Tracking Mode', 'Individual', false]
  ] : [
    ['Batch ID', assetId, true],
    ['Equipment', assetName, false],
    ['Category', category, false],
    ['Type', type, false],
    ['Tracking Mode', 'Batch', false]
  ];

  document.getElementById('qrModalMeta').innerHTML = rows.map(([k, v, accent]) =>
    `<div style="display:flex; justify-content:space-between; font-size:11px;"><span style="color:var(--text-dim);">${k}</span><span style="color:var(--text); font-weight:500; ${accent ? 'color:var(--gold);' : ''}">${v}</span></div>`
  ).join('');

  // Generate fallback QR code using canvas
  const qrContainer = document.getElementById('qrcode');
  qrContainer.innerHTML = '';

  const canvas = document.createElement('canvas');
  canvas.width = 200;
  canvas.height = 200;
  const ctx = canvas.getContext('2d');

  // Draw a simple placeholder QR code pattern
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, 200, 200);

  ctx.fillStyle = '#000000';

  // Create a simple pattern that looks like a QR code
  const cellSize = 4;
  for (let i = 0; i < 50; i++) {
    for (let j = 0; j < 50; j++) {
      if (Math.random() > 0.5 || (i < 7 && j < 7) || (i >= 43 && j < 7) || (i < 7 && j >= 43)) {
        ctx.fillRect(i * cellSize, j * cellSize, cellSize, cellSize);
      }
    }
  }

  // Add corner squares (QR code pattern)
  drawCornerSquare(ctx, 0, 0, cellSize);
  drawCornerSquare(ctx, 43 * cellSize, 0, cellSize);
  drawCornerSquare(ctx, 0, 43 * cellSize, cellSize);

  qrContainer.appendChild(canvas);

  const qrModal = document.getElementById('qrModal');
  const qrModalContent = document.getElementById('qrModalContent');
  if (qrModal) {
    qrModal.style.display = 'flex';
    qrModal.classList.add('on');
  }
  if (qrModalContent) qrModalContent.classList.add('open');
  document.body.style.overflow = 'hidden';
}

function drawCornerSquare(ctx, x, y, cellSize) {
  // Outer square
  ctx.fillStyle = '#000000';
  ctx.fillRect(x, y, 7 * cellSize, 7 * cellSize);

  // Inner white square
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(x + cellSize, y + cellSize, 5 * cellSize, 5 * cellSize);

  // Inner black square
  ctx.fillStyle = '#000000';
  ctx.fillRect(x + 2 * cellSize, y + 2 * cellSize, 3 * cellSize, 3 * cellSize);
}

function downloadQR() {
  if (!currentQRData) {
    alert('No QR data available');
    return;
  }

  // Build printable canvas
  const canvas = document.createElement('canvas');
  const W = 320, H = 380;
  canvas.width = W; canvas.height = H;
  const ctx = canvas.getContext('2d');

  // Background
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, W, H);

  // Header bar
  ctx.fillStyle = '#111111';
  ctx.fillRect(0, 0, W, 44);
  ctx.fillStyle = '#c4c43c';
  ctx.font = 'bold 13px monospace';
  ctx.textAlign = 'center';
  ctx.fillText('Halden\'s · Equipment ID', W / 2, 28);

  // QR image
  const qrImg = document.querySelector('#qrcode img') || document.querySelector('#qrcode canvas');
  if (qrImg) {
    if (qrImg.tagName === 'CANVAS') {
      ctx.drawImage(qrImg, 60, 60, 200, 200);
    } else {
      const img = new Image();
      img.src = qrImg.src;
      img.onload = () => {
        ctx.drawImage(img, 60, 60, 200, 200);
        finishCanvas(canvas, ctx, currentQRData, W, H);
      };
      return;
    }
  }

  finishCanvas(canvas, ctx, currentQRData, W, H);
}

function finishCanvas(canvas, ctx, d, W, H) {
  ctx.fillStyle = '#111';
  ctx.font = 'bold 15px monospace';
  ctx.textAlign = 'center';
  ctx.fillText(d.id, W / 2, 282);

  ctx.fillStyle = '#555';
  ctx.font = '12px sans-serif';
  ctx.fillText(d.name + (d.isIndividual ? ' — Individual Unit' : ' — Batch'), W / 2, 304);

  ctx.fillStyle = '#999';
  ctx.font = '10px monospace';
  ctx.fillText(d.category, W / 2, 324);

  // Border
  ctx.strokeStyle = '#eee';
  ctx.lineWidth = 2;
  ctx.strokeRect(1, 1, W - 2, H - 2);

  // Download
  const link = document.createElement('a');
  link.download = `QR_${d.id}.png`;
  link.href = canvas.toDataURL('image/png');
  link.click();
}

function printQR() {
  if (!currentQRData) {
    alert('No QR data available');
    return;
  }

  const qrImg = document.querySelector('#qrcode img') || document.querySelector('#qrcode canvas');
  let imgSrc = '';
  if (qrImg) imgSrc = qrImg.tagName === 'CANVAS' ? qrImg.toDataURL() : qrImg.src;

  const win = window.open('', '_blank');
  win.document.write(`
    <!DOCTYPE html>
    <html>
    <head>
      <title>QR Code - ${currentQRData.id}</title>
      <style>
        body { margin:0; padding:20px; font-family:monospace; text-align:center; }
        .qr-container { display:inline-block; padding:20px; border:2px solid #333; background:white; }
        .header { background:#111; color:#c4c43c; padding:10px; font-weight:bold; margin:-20px -20px 20px -20px; }
        .id { font-size:18px; font-weight:bold; margin:10px 0; }
        .name { font-size:14px; color:#555; margin:5px 0; }
        .category { font-size:12px; color:#999; }
      </style>
    </head>
    <body>
      <div class="qr-container">
        <div class="header">Halden's · Equipment ID</div>
        \${imgSrc ? \`<img src="\${imgSrc}" style="width:200px; height:200px;">\` : '<p>QR Code not available</p>'}
        <div class="id">\${currentQRData.id}</div>
        <div class="name">\${currentQRData.name} \${currentQRData.isIndividual ? '— Individual Unit' : '— Batch'}</div>
        <div class="category">\${currentQRData.category}</div>
      </div>
      <script>
        window.onload = function() {
          window.print();
          window.onafterprint = function() {
            window.close();
          };
        };
      </script>
    </body>
    </html>
  `);
}

// ===== DYNAMIC EIM CATEGORY FILTERS =====
function updateEIMCategoryFilters() {
  const filterContainer = document.getElementById('eim-cat-filter');
  if (!filterContainer) return;
  
  const uniqueCats = Array.from(new Set(EIM_ASSETS.map(a => a.category))).filter(Boolean).sort();
  const catsStr = uniqueCats.join('|');
  if (filterContainer.dataset.cats === catsStr && filterContainer.children.length > 0) return;
  
  filterContainer.dataset.cats = catsStr;
  
  if (!uniqueCats.includes(eimCurrentCat) && eimCurrentCat !== 'All') {
    eimCurrentCat = 'All';
  }

  filterContainer.innerHTML = '';
  
  const allBtn = document.createElement('button');
  allBtn.className = 'eim-cat-btn' + (eimCurrentCat === 'All' ? ' active' : '');
  allBtn.textContent = 'All';
  allBtn.onclick = function() { filterEIMCat('All', this); };
  filterContainer.appendChild(allBtn);

  uniqueCats.forEach(cat => {
    const btn = document.createElement('button');
    btn.className = 'eim-cat-btn' + (eimCurrentCat === cat ? ' active' : '');
    btn.textContent = cat;
    btn.onclick = function() { filterEIMCat(cat, this); };
    filterContainer.appendChild(btn);
  });
}

// ===== RENDER EIM TABLE =====
function renderEIMTable() {
  updateEIMCategoryFilters();
  renderEIMStats();

  const tbody = document.getElementById('eim-tbody');
  if (!tbody) return;

  let filtered = [];
  try {
    const search = (document.getElementById('eim-search') || {}).value || '';
    filtered = EIM_ASSETS.filter(a => {
      const matchCat = eimCurrentCat === 'All' || a.category === eimCurrentCat;
      const q = search.toLowerCase();
      const matchSearch = !q ||
        (a.name || '').toLowerCase().includes(q) ||
        (a.id || '').toLowerCase().includes(q) ||
        (a.type || '').toLowerCase().includes(q) ||
        (a.supplier || '').toLowerCase().includes(q);
      return matchCat && matchSearch;
    });
  } catch (err) {
    console.error('Crash in renderEIMTable filter:', err);
    tbody.innerHTML = `<tr><td colspan="9" style="text-align:center;padding:32px;color:red;"><b>Error rendering table:</b> ${err.message}</td></tr>`;
    return;
  }

  const condColors = { Excellent: 'var(--green)', Good: 'var(--gold)', Fair: 'var(--amber)', Poor: 'var(--red)', Damaged: 'var(--red)' };
  const statColors = { Active: 'confirmed', 'Available': 'confirmed', 'In Use': 'pending', 'Under Repair': 'critical', 'Maintenance': 'critical', 'Retired': 'cancelled', 'Review': 'warning' };

  if (!filtered.length) {
    tbody.innerHTML = `<tr><td colspan="9" style="text-align:center;padding:32px;color:var(--text-dim);">No equipment found.</td></tr>`;
    return;
  }

  let html = '';
  filtered.forEach((a) => {
    const origIdx = EIM_ASSETS.indexOf(a);

    let displayCond = a.condition;
    let displayStat = a.status;
    let activeQty = a.quantity;
    let availableQty = a.availableQty != null ? a.availableQty : activeQty;

    if (a.trackingMode === 'batch' && a.items && a.items.length > 0) {
      const poorCount = a.items.filter(i => i.condition === 'Damaged' || i.condition === 'Poor').length;
      if (poorCount > 0) displayCond = 'Damaged';
      else if (a.items.some(i => i.condition === 'Fair')) displayCond = 'Fair';
      else if (a.items.every(i => i.condition === 'Excellent')) displayCond = 'Excellent';
      else displayCond = 'Good';

      if (a.items.some(i => i.status === 'Retired')) displayStat = 'Review';
      else if (a.items.some(i => i.status === 'Under Repair')) displayStat = 'Maintenance';
      else displayStat = 'Available';

      activeQty = a.items.length;
      
      const damagedCount = a.items.filter(i => i.condition === 'Damaged' || i.condition === 'Poor' || i.status === 'Retired').length;
      availableQty = activeQty - damagedCount;
    } else {
      displayCond = a.condition;
      displayStat = a.status === 'Active' ? 'Available' : a.status;
    }

    const totalVal = (a.unitCost * activeQty).toLocaleString();
    const trackBadge = a.trackingMode === 'individual'
      ? `<span style="font-size:12px; color:var(--text);">Individual</span>`
      : `<span style="font-size:12px; color:var(--text); cursor:pointer;" onclick="toggleEimSubRow('${a.id}')">Batch ▽<br><small style="color:var(--text-dim);">${a.batchTrackingId}</small></span>`;

    const supplierTxt = a.supplier
      ? `<div style="font-size:12px;color:var(--text);">${a.supplier}</div>`
      : `<div style="font-size:11px;color:var(--text-dim);"> ${a.sourceLocation || '—'}</div>`;

    let mainRowIdDisplay = a.id;
    if (a.trackingMode === 'batch' && a.batchTrackingId) {
      mainRowIdDisplay = a.batchTrackingId;
    }

    html += `
      <tr class="eim-main-row" id="eim-row-${a.id}">
        <td><span style="font-size:12px; color:var(--text);">${mainRowIdDisplay}</span></td>
        <td>
          <div class="item-name">${a.name}</div>
          <div class="item-cat">${a.type}</div>
        </td>
        <td><span style="font-size:12px; color:var(--text);">${a.category}</span></td>
        <td style="font-size:13px; font-weight:600;">${activeQty} <span style="color:var(--text-dim);font-size:11px;">${a.unitType}</span></td>
        <td>${(() => {
          const mq = a.maintenance_qty || 0;
          const rq = (a.missing_qty||0) + (a.retired_qty||0);
          let sc, cc;
          if (mq > 0 && rq > 0)  { sc = 'Needs Maintenance & Resupply'; cc = 'var(--red)'; }
          else if (mq > 0)        { sc = 'Needs Maintenance';  cc = 'var(--amber)'; }
          else if (rq > 0)        { sc = 'Needs Resupply';     cc = 'var(--amber)'; }
          else {
            const r = displayCond || '';
            if (r === 'Damaged' || r === 'Poor') { sc = 'Needs Maintenance'; cc = 'var(--red)'; }
            else { sc = 'Good'; cc = 'var(--green)'; }
          }
          return '<span style="font-size:12px;font-weight:600;color:'+cc+';">'+sc+'</span>';
        })()}</td>
        <td>
          <div style="font-size:13px;font-weight:600;font-family:'Arial',serif;">₱${a.unitCost.toLocaleString()}</div>
          <div style="font-size:10px;color:var(--text-dim);">Total ₱${totalVal}</div>
        </td>
        <td>${supplierTxt}</td>
        <td>${trackBadge}</td>
        <td style="text-align:right; white-space:nowrap;">
          <button class="btn-primary" style="margin-right:4px; font-size:10px; padding:4px 8px;" onclick="showEquipmentQR('${a.id}', null)">Batch QR</button>
          <button class="btn-view" style="margin-right:4px;" onclick="openEditEquipmentModal(${origIdx})">Edit</button>
          <button class="btn-reject" onclick="confirmDeleteEquipment(${origIdx})"></button>
        </td>
      </tr>`;

    // Render Sub-rows if batch natively embedded
    if (a.trackingMode === 'batch' && a.items) {
      a.items.forEach((sub, sIdx) => {
        const iStat = sub.status === 'Active' ? 'Available' : sub.status;
        html += `
          <tr class="eim-sub-row eim-sub-${a.id}" style="display:none; background:var(--bg2);">
            <td style="padding-left:16px;"><code style="font-size:10px;">${sub.subId}</code></td>
            <td style="color:var(--text-dim); font-size:12px;">↳ ${a.name} (Unit)</td>
            <td></td>
            <td style="font-size:12px;color:var(--text-dim);">1 ${a.unitType}</td>
            <td style="font-size:12px;color:var(--text-dim);">—</td>
            <td><span style="font-size:11px; color:${condColors[sub.condition]}">● ${sub.condition}</span></td>
            <td><span class="badge ${statColors[iStat] || 'pending'}" style="font-size:10px;">${iStat}</span></td>
            <td style="font-size:12px;">₱${a.unitCost.toLocaleString()}</td>
            <td>${supplierTxt}</td>
            <td><span style="font-size:10px; color:var(--text-dim);">Unit Level</span></td>
            <td style="text-align:right;">
              ${shouldHaveIndividualQR(a.category)
            ? `<button class="btn-primary" style="margin-right:4px; font-size:9px; padding:2px 6px;" onclick="showEquipmentQR('${a.id}', '${sub.subId}')"> QR</button>`
            : ''
          }
              <button class="btn-outline" style="font-size:10px; padding:2px 8px;" onclick="openEditIndividualModal(${origIdx}, ${sIdx})">Edit Unit</button>
            </td>
          </tr>`;
      });
    }
  });

  tbody.innerHTML = html;
}

function toggleEimSubRow(id) {
  const rows = document.querySelectorAll('.eim-sub-' + id);
  let isHidden = rows.length > 0 && rows[0].style.display === 'none';
  rows.forEach(tr => { tr.style.display = isHidden ? 'table-row' : 'none'; });
}
function openEditIndividualModal(bIdx, sIdx) {
  const asset = EIM_ASSETS[bIdx]; const item = asset.items[sIdx];
  document.getElementById('eim-edit-indiv-batch-idx').value = bIdx;
  document.getElementById('eim-edit-indiv-item-idx').value = sIdx;
  document.getElementById('eim-edit-indiv-id').value = item.subId;
  document.getElementById('eim-edit-indiv-condition').value = item.condition;
  document.getElementById('eim-edit-indiv-status').value = item.status;
  document.getElementById('eim-edit-indiv-modal').classList.add('open');
  document.getElementById('eim-edit-indiv-overlay').classList.add('on');
}
function closeEditIndividualModal() {
  document.getElementById('eim-edit-indiv-modal').classList.remove('open');
  document.getElementById('eim-edit-indiv-overlay').classList.remove('on');
}
const EIM_LOGS = [];
function recordEIMLog(action, details) {
  const userStr = sessionStorage.getItem('halden_admin');
  let user = 'Staff';
  if (userStr) { try { const u = JSON.parse(userStr); user = u.role === 'admin' ? 'Admin' : (u.name || 'Staff'); } catch(e){} }
  EIM_LOGS.unshift({ time: new Date().toLocaleString(), user, action, details });
  renderEIMLogs();
}
function renderEIMLogs() {
  const tbody = document.getElementById('eim-logs-tbody');
  if (!tbody) return;
  if (!EIM_LOGS.length) { tbody.innerHTML = '<tr><td colspan="3" style="text-align:center;padding:24px;color:var(--text-dim);">No activity logs available.</td></tr>'; return; }
  tbody.innerHTML = EIM_LOGS.map(l => '<tr><td style="font-size:12px;color:var(--text-dim);">' + l.time + '</td><td><span class="badge pending" style="font-size:11px;">' + l.user + '</span></td><td><div style="font-weight:600;font-size:13px;">' + l.action + '</div><div style="font-size:11px;color:var(--text-dim);margin-top:2px;">' + l.details + '</div></td></tr>').join('');
}
function submitEditIndividual() {
  const bIdx = document.getElementById('eim-edit-indiv-batch-idx').value;
  const sIdx = document.getElementById('eim-edit-indiv-item-idx').value;
  const asset = EIM_ASSETS[bIdx]; const item = asset.items[sIdx];
  const oldCond = item.condition; const oldStat = item.status;
  const newCond = document.getElementById('eim-edit-indiv-condition').value;
  const newStat = document.getElementById('eim-edit-indiv-status').value;
  if (oldCond !== newCond || oldStat !== newStat) { item.condition = newCond; item.status = newStat; recordEIMLog('Item Status Updated', item.subId + ' updated'); renderEIMTable(); }
  closeEditIndividualModal();
}
window.toggleEimSubRow = toggleEimSubRow;
window.openEditIndividualModal = openEditIndividualModal;
window.closeEditIndividualModal = closeEditIndividualModal;
window.submitEditIndividual = submitEditIndividual;

function filterEIMCat(cat, btn) {
  eimCurrentCat = cat;
  document.querySelectorAll('.eim-cat-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  renderEIMTable();
}
window.filterEIMCat = filterEIMCat;

function switchEIMPnl(val) {
  const pnlList  = document.getElementById('eim-pnl-list');
  const pnlLogs  = document.getElementById('eim-pnl-logs');
  const pnlAlloc = document.getElementById('eim-pnl-allocations');
  const pnlRental = document.getElementById('eim-pnl-rental-history');
  if (pnlList)  pnlList.style.display  = val === 'list'        ? 'block' : 'none';
  if (pnlLogs)  pnlLogs.style.display  = val === 'logs'        ? 'block' : 'none';
  if (pnlAlloc) pnlAlloc.style.display = val === 'allocations' ? 'block' : 'none';
  if (pnlRental) pnlRental.style.display = val === 'rental-history' ? 'block' : 'none';
  const tList  = document.getElementById('tab-eim-list');
  const tLogs  = document.getElementById('tab-eim-logs');
  const tAlloc = document.getElementById('tab-eim-alloc');
  const tRental = document.getElementById('tab-eim-rental-history');
  if (tList)  tList.classList.toggle('active',  val === 'list');
  if (tLogs)  tLogs.classList.toggle('active',  val === 'logs');
  if (tAlloc) tAlloc.classList.toggle('active', val === 'allocations');
  if (tRental) tRental.classList.toggle('active', val === 'rental-history');
  if (val === 'allocations') switchAllocTab('availability');
  if (val === 'rental-history') renderEqRentalHistory();
}
window.switchEIMPnl = switchEIMPnl;

function switchAllocTab(tab) {
  const avPanel  = document.getElementById('eim-avail-panel');
  const alcPanel = document.getElementById('eim-alloc-panel');
  const avTab    = document.getElementById('alloc-tab-avail');
  const alcTab   = document.getElementById('alloc-tab-alloc');
  if (avPanel)  avPanel.style.display  = tab === 'availability' ? 'block' : 'none';
  if (alcPanel) alcPanel.style.display = tab === 'allocations'  ? 'block' : 'none';
  if (avTab)  { avTab.style.color  = tab === 'availability' ? 'var(--gold)' : 'var(--text-dim)'; avTab.style.borderBottomColor = tab === 'availability' ? 'var(--gold)' : 'transparent'; }
  if (alcTab) { alcTab.style.color = tab === 'allocations'  ? 'var(--gold)' : 'var(--text-dim)'; alcTab.style.borderBottomColor = tab === 'allocations'  ? 'var(--gold)' : 'transparent'; }
  if (tab === 'availability') loadAvailabilityView();
  if (tab === 'allocations')  loadViewAllocations();
}
window.switchAllocTab = switchAllocTab;

function toggleAllocDetail(hdr) {
  const det = hdr.parentElement.querySelector('.alloc-detail');
  if (det) det.style.display = det.style.display === 'none' ? 'block' : 'none';
}
window.toggleAllocDetail = toggleAllocDetail;

async function loadViewAllocations() {
  const container = document.getElementById('eim-alloc-list-inner');
  if (!container) return;
  container.innerHTML = '<div style="text-align:center;padding:40px;color:var(--text-dim);font-size:13px;">Loading allocations...</div>';
  const sb = window.supabaseClient;
  if (!sb) { container.innerHTML = '<div style="padding:20px;color:var(--red);">Supabase not available.</div>'; return; }

  // Read from allocation_history — each reservation's batch is stored as separate INSERT rows,
  // so multiple reservations on the same date/client each have their own independent records.
  const { data, error } = await sb
    .from('allocation_history')
    .select('allocation_batch,reservation_id,reservation_name,asset_id,equipment_name,allocated_qty,recorded_at,is_rental')
    .not('allocation_batch', 'is', null)
    .order('recorded_at', { ascending: false });

  if (error || !data || !data.length) {
    container.innerHTML = '<div style="text-align:center;padding:40px;color:var(--text-dim);font-size:13px;">No allocations found. Allocate equipment in Equipment Cycle first.</div>';
    return;
  }
  
  let allocs = data;
  const dedupMap = {};
  allocs.forEach(h => {
    if (!h.reservation_id) return;
    const isVenue = h.allocation_batch && h.allocation_batch.startsWith('VENUE-');
    const key = `${h.reservation_id}_${h.equipment_name || h.asset_id}_${h.is_rental}_${!!isVenue}`;
    const time = h.recorded_at ? new Date(h.recorded_at).getTime() : 0;
    if (!dedupMap[key] || time > dedupMap[key].time) {
      dedupMap[key] = { row: h, time };
    }
  });
  allocs = Object.values(dedupMap).map(d => d.row);

  // Group by reservation_id (unique per reservation even if batch names collide)
  const batches = {};
  allocs.forEach(row => {
    const bKey = row.reservation_id || row.allocation_batch;
    if (!batches[bKey]) {
      batches[bKey] = { batchName: row.allocation_batch, reservationId: row.reservation_id, allocatedTo: row.reservation_name, items: [] };
    }
    batches[bKey].items.push({ name: row.equipment_name, category: '', assetId: row.asset_id, qty: row.allocated_qty, is_rental: row.is_rental, is_venue: row.allocation_batch && row.allocation_batch.startsWith('VENUE-') });
  });

  const batchList = Object.values(batches).sort((a, b) => a.batchName.localeCompare(b.batchName));

  // Filter out batches that belong to cancelled reservations, and wipe them from equipment_inventory
  const validBatchList = [];
  batchList.forEach(batch => {
    const res = RESERVATIONS ? RESERVATIONS.find(r => r.id === batch.reservationId || (r.client || r.name || '').toLowerCase() === (batch.allocatedTo || '').toLowerCase()) : null;
    if (res && res.status === 'cancelled') {
      if (sb && batch.reservationId) {
        sb.from('equipment_inventory')
          .update({ allocated_qty: 0, allocation_batch: null, allocated_to: null, allocated_reservation_id: null, allocation_date: null })
          .eq('allocated_reservation_id', batch.reservationId)
          .then(() => console.log('Cleaned up orphaned batch for cancelled reservation:', batch.reservationId))
          .catch(e => console.warn('Failed to clean up orphaned batch:', e));
      }
      return; // Skip rendering
    }
    validBatchList.push(batch);
  });

  container.innerHTML = validBatchList.map(batch => {
    const res = RESERVATIONS ? RESERVATIONS.find(r => r.id === batch.reservationId || (r.client || r.name || '').toLowerCase() === (batch.allocatedTo || '').toLowerCase()) : null;
    const resName = res ? (res.packageName || res.type || 'Event') : (batch.allocatedTo || 'Unknown');
    const customer = res ? (res.client || res.customerName || batch.allocatedTo || '—') : (batch.allocatedTo || '—');
    const timeRange = res ? ((res.eventTimeStart || res.startTime || '') + (res.eventTimeEnd || res.endTime ? ' — ' + (res.eventTimeEnd || res.endTime) : '')) : '—';
    const formatResDate = (dStr) => {
      if (!dStr) return null;
      const d = new Date(dStr);
      if (!isNaN(d.getTime())) return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
      return dStr;
    };
    const dateStr = res ? formatResDate(res.date || res.eventDate || null) : '';
    const venue = res ? (res.venue || res.venueAddress || res.location || '') : '';
    const mapUrl = venue ? 'https://maps.google.com/maps?q=' + encodeURIComponent(venue) + '&output=embed' : '';
    let isModified = false;
    if (res && typeof _genBatchName === 'function' && typeof _getBatchModificationString === 'function') {
      const expectedBatch = _genBatchName(res);
      if (batch.batchName !== expectedBatch) {
         const changeStr = _getBatchModificationString(batch.batchName, expectedBatch);
         if (changeStr && changeStr !== 'No significant changes detected.') {
            isModified = true;
         }
      }
    }

    const itemRows = batch.items.map(i => {
      let badgeHtml = '';
      if (i.is_venue) {
        badgeHtml = ' <span class="badge confirmed" style="font-size:9px;padding:2px 4px;margin-left:4px;background:rgba(45,138,78,0.1);color:var(--green);border:1px solid var(--green);">Venue Provided</span>';
      } else if (i.is_rental) {
        badgeHtml = ' <span class="badge confirmed" style="font-size:9px;padding:2px 4px;margin-left:4px;background:rgba(196,154,60,0.1);color:var(--gold);border:1px solid var(--gold);">Rental</span>';
      }
      return '<tr><td style="font-size:12px;padding:6px 10px;"><span style="color:var(--text);">' + (i.assetId||'') + '</span></td><td style="font-size:12px;padding:6px 10px;">' + (i.name||'') + badgeHtml + '</td><td style="font-size:11px;padding:6px 10px;"><span style="color:var(--text);">' + (i.category||'') + '</span></td><td style="font-size:13px;font-weight:700;padding:6px 10px;color:var(--gold);">' + (i.qty||0) + '</td></tr>';
    }).join('');
    return '<div class="panel" style="margin-bottom:14px;border:1px solid var(--border);border-radius:12px;overflow:hidden;">' +
      '<div style="display:flex;align-items:center;justify-content:space-between;padding:14px 18px;cursor:pointer;gap:12px;" onclick="toggleAllocDetail(this)">' +
        '<div>' +
          '<div style="display:flex;align-items:center;gap:10px;margin-bottom:4px;">' +
            '<span style="font-size:12px;font-weight:700;color:var(--gold);text-transform:uppercase;">' + batch.batchName + '</span>' +
            (dateStr ? '<span style="font-size:11px;color:var(--text-dim);">' + dateStr + '</span>' : '') +
          '</div>' +
          '<div style="font-size:13px;font-weight:600;color:var(--cream);">' + customer + ' — ' + resName + '</div>' +
          (timeRange && timeRange !== '—' ? '<div style="font-size:11px;color:var(--text-dim);margin-top:2px;">' + timeRange + '</div>' : '') +
          (isModified ? '<div style="font-size:11px;color:var(--gold);margin-top:4px;font-weight:600;">\u26a0\ufe0f Package significantly modified, allocation needs an update</div>' : '') +
        '</div>' +
        '<div style="display:flex;gap:8px;flex-shrink:0;">' +
          '<button class="btn-primary" style="font-size:11px;padding:5px 10px;" onclick="event.stopPropagation();generateBatchQR(&quot;' + batch.batchName + '&quot;, &quot;' + batch.reservationId + '&quot;)">View QR</button>' +
          '<button class="btn-outline" style="font-size:11px;padding:5px 10px;" onclick="event.stopPropagation();jumpToEqcForBatch(&quot;' + (batch.reservationId||batch.allocatedTo) + '&quot;)">Modify</button>' +
          '<span style="font-size:11px;color:var(--text-dim);align-self:center;">' + batch.items.length + ' items</span>' +
        '</div>' +
      '</div>' +
      '<div class="alloc-detail" style="display:none;border-top:1px solid var(--border);">' +
        (mapUrl ? '<iframe src="' + mapUrl + '" width="100%" height="200" style="border:none;display:block;"></iframe>' : (venue ? '<div style="padding:10px 18px;font-size:12px;color:var(--text-dim);">Venue: ' + venue + '</div>' : '')) +
        '<div style="padding:10px 18px;">' +
          '<table style="width:100%;border-collapse:collapse;">' +
            '<thead><tr style="border-bottom:1px solid var(--border);"><th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Asset ID</th><th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Equipment</th><th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Category</th><th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Qty</th></tr></thead>' +
            '<tbody>' + itemRows + '</tbody>' +
          '</table>' +
        '</div>' +
      '</div>' +
    '</div>';
  }).join('');
}

// ====== AVAILABILITY VIEW ======
async function loadAvailabilityView() {
  const container = document.getElementById('eim-avail-list');
  if (!container) return;
  container.innerHTML = '<div style="text-align:center;padding:40px;color:var(--text-dim);font-size:13px;">Loading availability...</div>';
  const sb = window.supabaseClient;
  if (!sb) { container.innerHTML = '<div style="padding:20px;color:var(--red);">Supabase not available.</div>'; return; }

  let eqRows = [];
  try {
    const [resEq, resHist] = await Promise.all([
      sb.from('equipment_inventory').select('id,asset_id,name,category,total_qty'),
      sb.from('allocation_history').select('asset_id,equipment_name,allocated_qty,reservation_id,reservation_name,allocation_batch,is_rental,recorded_at').not('allocation_batch', 'is', null)
    ]);
    if (resEq.error) throw resEq.error;
    if (resHist.error) throw resHist.error;

    const baseEq = resEq.data || [];
    let histData = resHist.data || [];

    // Deduplicate existing history data to self-heal old duplicate batches
    const dedupMap = {};
    histData.forEach(h => {
      if (!h.reservation_id) return;
      const isVenue = h.allocation_batch && h.allocation_batch.startsWith('VENUE-');
      const key = `${h.reservation_id}_${h.equipment_name || h.asset_id}_${h.is_rental}_${!!isVenue}`;
      const time = h.recorded_at ? new Date(h.recorded_at).getTime() : 0;
      if (!dedupMap[key] || time > dedupMap[key].time) {
        dedupMap[key] = { row: h, time };
      }
    });
    histData = Object.values(dedupMap).map(d => d.row);

    // Push base unallocated rows so every asset exists (for total_qty reference)
    baseEq.forEach(eq => {
      eqRows.push({
        ...eq,
        allocated_qty: 0,
        rented_qty: 0,
        allocated_reservation_id: null,
        allocated_to: null,
        allocation_batch: null
      });
    });

    // Push historical allocation rows
    histData.forEach(h => {
      const eq = baseEq.find(e => (e.asset_id || '').toUpperCase() === (h.asset_id || '').toUpperCase()) || {};
      const isVenue = h.allocation_batch && h.allocation_batch.startsWith('VENUE-');
      eqRows.push({
        id: eq.id || h.asset_id,
        asset_id: h.asset_id,
        name: h.equipment_name || eq.name,
        category: eq.category,
        total_qty: eq.total_qty,
        allocated_qty: (h.is_rental || isVenue) ? 0 : h.allocated_qty,
        rented_qty: h.is_rental ? h.allocated_qty : 0,
        venue_qty: isVenue ? h.allocated_qty : 0,
        allocated_reservation_id: h.reservation_id,
        allocated_to: h.reservation_name,
        allocation_batch: h.allocation_batch
      });
    });
  } catch (err) {
    console.warn('[Availability] Supabase fetch failed:', err);
    container.innerHTML = '<div style="padding:20px;color:var(--red);">Failed to load equipment data from Supabase.</div>';
    return;
  }
  const allEquip = eqRows || [];

  const byAssetId = {};
  allEquip.forEach(row => {
    const key = (row.asset_id || '').toUpperCase().trim();
    if (key) {
      if (!byAssetId[key]) byAssetId[key] = [];
      byAssetId[key].push(row);
    }
  });

  // ── Build a "standard equipment template" from all batches ever saved ──
  // Keyed by asset_id → Supabase row. Used for unallocated reservations so
  // they show the same complete item list as allocated ones.
  const standardEqTemplate = {}; // asset_id.toUpperCase() → { eq, templateAllocQty }
  allEquip.forEach(e => {
    if (!e.allocation_batch || !e.asset_id || e.allocation_batch.startsWith('VENUE-')) return;
    const key = e.asset_id.toUpperCase();
    // Keep the first occurrence (or the one with largest allocated_qty as reference)
    const combinedQty = (parseInt(e.allocated_qty) || 0) + (parseInt(e.rented_qty) || 0);
    if (!standardEqTemplate[key] || combinedQty > (standardEqTemplate[key].templateAllocQty || 0)) {
      standardEqTemplate[key] = { eq: e, templateAllocQty: combinedQty };
    }
  });

  // Find the pax for the reservation that provided the template
  // We use this to scale Required quantities proportionally for other reservations.
  let templatePax = 0;
  const templateResIds = new Set(Object.values(standardEqTemplate).map(t => t.eq.allocated_reservation_id).filter(Boolean));
  templateResIds.forEach(rid => {
    if (templatePax) return;
    const tRes = (RESERVATIONS || []).find(r => r.id === rid);
    if (tRes && parseInt(tRes.pax) > 0) templatePax = parseInt(tRes.pax);
  });
  if (!templatePax) templatePax = 1; // safe fallback

  window._availCurrentFilter = window._availCurrentFilter || 'All';
  
  let targetRes = (RESERVATIONS || []).filter(r => {
    const s = (r.status || '').toLowerCase();
    const isApproved = s.includes('confirm') || s.includes('planning') || s.includes('procurement') || s.includes('preparation') || s.includes('on-going');
    const isPending = s.includes('pending') || s.includes('review');
    
    if (window._availCurrentFilter === 'Approved') return isApproved;
    if (window._availCurrentFilter === 'Pending') return isPending;
    return isApproved || isPending;
  });

  // Helper to format dates consistently
  const formatResDate = (dStr) => {
    if (!dStr) return null;
    const d = new Date(dStr);
    if (!isNaN(d.getTime())) return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
    return dStr;
  };

  // Sort by date chronologically
  targetRes.sort((a, b) => {
    const da = a.date || a.eventDate || '';
    const db = b.date || b.eventDate || '';
    const timeA = da ? new Date(da).getTime() : 0;
    const timeB = db ? new Date(db).getTime() : 0;
    if (!isNaN(timeA) && !isNaN(timeB)) return timeA - timeB;
    return da.localeCompare(db);
  });

  if (!targetRes.length) {
    container.innerHTML = '<div style="text-align:center;padding:40px;color:var(--text-dim);font-size:13px;">No reservations found for the selected filter.</div>';
    return;
  }

  let lastDateGroup = null;
  const cards = targetRes.map(res => {
    const resDate = formatResDate(res.date || res.eventDate || null);
    const resId   = res.id;
    const pax     = parseInt(res.pax) || 0;
    const tablesNeeded = Math.ceil(pax / 8);

    let menuItemCount = 1;
    if (res.packageItems && typeof CAT !== 'undefined') {
       menuItemCount = res.packageItems.map(n => CAT.find(c => c.name === (typeof n === 'string' ? n : n.name))).filter(i => i && i.cat === 'food').length || 1;
    }

    const calcQty = (aKey, assetRuleFallback) => {
        const realAsset = typeof window.findAssetForRule === 'function' ? window.findAssetForRule({ assetId: aKey }) : null;
        const fallback = assetRuleFallback || (realAsset ? realAsset.allocationRule || realAsset.allocation_type : 'fixed');
        const r = (fallback || 'fixed').toLowerCase();
        if (r === 'per_pax') return pax;
        else if (r === 'per_5_pax') return Math.ceil(pax / 5);
        else if (r === 'per_8_pax') return Math.ceil(pax / 8);
        else if (r === 'per_10_pax') return Math.ceil(pax / 10);
        else if (r === 'per_table') return tablesNeeded;
        else if (r === 'per_menu_item') return menuItemCount;
        else if (r === 'fixed' || r === 'flat') return 1;
        return pax; // ultimate fallback
    };

    const bufF = (parseFloat((document.getElementById('alloc-buffer-fragile') || {}).value || '15') || 15) / 100;
    const bufS = (parseFloat((document.getElementById('alloc-buffer-sturdy') || {}).value || '10') || 10) / 100;

    const calcBuffer = (qty, aKey) => {
        const eqList = aKey ? (byAssetId[aKey] || []) : [];
        const asset = eqList[0] || {};
        const lowName = (asset.name || '').toLowerCase();
        let buffer = 0;
        if (asset.isFragile || lowName.includes('plate') || lowName.includes('glass') || lowName.includes('cup')) {
            buffer = Math.ceil(qty * bufF);
        } else if (qty >= 50) {
            buffer = Math.ceil(qty * bufS);
        }
        return buffer;
    };

    // ── Step 1: Items ACTUALLY in this reservation's Supabase batch ──────
    // These are the ground truth — whatever was saved by Equipment Cycle.
    const rawBatchItems = allEquip.filter(e => e.allocated_reservation_id === resId && (e.asset_id || '').toUpperCase() !== 'VENUE');

    // Aggregate by asset_id to combine inventory and rental quantities
    const aggregatedBatchItems = {};
    rawBatchItems.forEach(eq => {
      let aKey = (eq.asset_id || '').toUpperCase().trim();
      
      if (!aKey) {
        const match = allEquip.find(e => (e.name || '').toLowerCase() === (eq.name || '').toLowerCase() && e.asset_id && e.asset_id.toUpperCase() !== 'VENUE');
        if (match) {
          aKey = (match.asset_id || '').toUpperCase().trim();
          eq.asset_id = match.asset_id;
          eq.total_qty = match.total_qty;
        } else {
          aKey = 'NAME-' + (eq.name || '').toUpperCase().trim();
        }
      }
      
      if (!aggregatedBatchItems[aKey]) {
        aggregatedBatchItems[aKey] = { ...eq, allocated_qty: 0, rented_qty: 0, venue_qty: 0 };
      }
      aggregatedBatchItems[aKey].allocated_qty += (parseInt(eq.allocated_qty) || 0);
      aggregatedBatchItems[aKey].rented_qty += (parseInt(eq.rented_qty) || 0);
      aggregatedBatchItems[aKey].venue_qty += (parseInt(eq.venue_qty) || 0);
    });
    const batchItems = Object.values(aggregatedBatchItems);

    // Build a set of asset_ids already covered by the batch
    const batchAssetIds = new Set(batchItems.map(e => (e.asset_id || '').toUpperCase().trim()).filter(Boolean));

    // ── Step 2: Build the supplemental item list for items NOT in batch ──
    // Priority order (highest fidelity first):
    //   2a) res.equipmentManifest  – exact quantities saved by Equipment Cycle
    //   2b) res.packageItems       – name strings from the reservation's package
    //   2c) standardEqTemplate     – inferred from other reservations' batches
    //   2d) ALLOC_RULES            – global rules as last resort
    const supplementRows = [];
    const seenInSupplement = new Set(batchAssetIds);

    // 2a) reservation's own equipmentManifest — highest fidelity, has exact asset IDs + qty
    if (res.equipmentManifest && res.equipmentManifest.length) {
      res.equipmentManifest.forEach(mItem => {
        const mKey = (mItem.assetId || '').toUpperCase().trim();
        if (mKey === 'VENUE' || (mKey && seenInSupplement.has(mKey))) return; // already in batch or legacy VENUE row
        const eqList = mKey ? (byAssetId[mKey] || []) : [];
        const eq = eqList[0] || { asset_id: mItem.assetId, name: mItem.name, total_qty: 0 };
        const needed = calcQty(mKey, eq.allocationRule || eq.allocation_type);
        if (needed <= 0) return;
        if (mKey) seenInSupplement.add(mKey);
        const buffer = calcBuffer(needed, mKey);
        supplementRows.push({ assetId: mItem.assetId || '—', name: mItem.name || '—', needed, buffer, eq });
      });
    }

    // 2b) res.packageItems — name strings from the reservation's package (fallback if manifest not yet generated)
    if (res.packageItems && res.packageItems.length) {
      const assets = window.EIM_ASSETS || [];
      res.packageItems.forEach(itemEntry => {
        const itemName = typeof itemEntry === 'string' ? itemEntry : (itemEntry.name || '');
        if (!itemName) return;
        // Match by name against EIM_ASSETS
        const asset = assets.find(a => (a.name || '').toLowerCase().trim() === itemName.toLowerCase().trim())
          || (typeof window.findAssetForRule === 'function' ? window.findAssetForRule({ name: itemName }) : null);
        if (!asset) return;
        const aKey = (asset.id || asset.asset_id || '').toUpperCase().trim();
        if (aKey && seenInSupplement.has(aKey)) return; // already covered
        
        let qty = calcQty(aKey, asset.allocationRule);
        if (qty <= 0) return;
        const eqList = aKey ? (byAssetId[aKey] || []) : [];
        const eq = eqList[0] || { asset_id: asset.id || asset.asset_id, name: asset.name, total_qty: asset.quantity || 0 };
        if (aKey) seenInSupplement.add(aKey);
        const buffer = calcBuffer(qty, aKey);
        supplementRows.push({ assetId: asset.id || asset.asset_id || '—', name: asset.name || itemName, needed: qty, buffer, eq });
      });
    }

    // 2c) standardEqTemplate — items inferred from other reservations' allocation batches
    // ONLY include template items that are actually in THIS reservation's packageItems.
    // This prevents equipment allocated to OTHER packages from leaking into unrelated reservations.
    const resPackageItemNames = new Set(
      (res.packageItems || []).map(n => (typeof n === 'string' ? n : (n && n.name) || '').toLowerCase().trim()).filter(Boolean)
    );
    Object.entries(standardEqTemplate).forEach(([key, tmpl]) => {
      if (seenInSupplement.has(key)) return; // Already covered by manifest/packageItems/batch
      const eq = tmpl.eq;
      // If this reservation has packageItems defined, only include template items that match
      if (resPackageItemNames.size > 0) {
        const tmplNameLower = (eq.name || '').toLowerCase().trim();
        if (!resPackageItemNames.has(tmplNameLower)) return; // Not in this reservation's package — skip
      }
      seenInSupplement.add(key);

      let needed = calcQty(key, eq.allocationRule || eq.allocation_type);
      if (!needed) needed = Math.ceil((tmpl.templateAllocQty / templatePax) * pax);

      if (needed <= 0) return;
      const buffer = calcBuffer(needed, key);
      supplementRows.push({ assetId: eq.asset_id || '—', name: eq.name || '—', needed, buffer, eq });
    });

    // 2d) ALLOC_RULES — global rules as last resort for items not yet seen
    // Only include if the item is actually in this reservation's packageItems (same gate as Step 2c)
    (ALLOC_RULES || []).forEach(rule => {
      if (!rule || !rule.name) return;
      const ruleKey = (rule.assetId || '').toUpperCase().trim();
      if (seenInSupplement.has(ruleKey)) return;
      // If this reservation has packageItems, skip ALLOC_RULES items not in the package
      if (resPackageItemNames.size > 0) {
        const ruleNameLower = (rule.name || '').toLowerCase().trim();
        if (!resPackageItemNames.has(ruleNameLower)) return;
      }
      seenInSupplement.add(ruleKey);
      const eqList = ruleKey ? (byAssetId[ruleKey] || []) : [];
      if (!eqList.length) return; // Not in Supabase, skip

      let qty = calcQty(ruleKey, 'fixed');
      if (qty <= 0) return;
      const buffer = calcBuffer(qty, ruleKey);
      supplementRows.push({ assetId: rule.assetId, name: rule.name, needed: qty, buffer, eq: eqList[0] });
    });


    // ── Step 3: Build unified display rows ───────────────────────────────
    // Pre-compute the set of other reservation IDs that share the same event date.
    // This is more reliable than comparing allocation_date on equipment rows because
    // that column may not exist or may be null in equipment_inventory.
    const sameDateResIds = new Set(
      (RESERVATIONS || [])
        .filter(r => r.id !== resId && formatResDate(r.date || r.eventDate || null) === resDate)
        .map(r => r.id)
    );
    const rows = [];

    // a) Batch items (this reservation's actual allocation — ground truth)
    batchItems.forEach(eq => {
      const aKey = (eq.asset_id || '').toUpperCase().trim();
      let needed = calcQty(aKey, eq.allocation_type || eq.allocationRule);
      const buffer = calcBuffer(needed, aKey);
      const totalReq = needed + buffer;
      const total = parseInt(eq.total_qty || 0);
      const allocatedToThis = parseInt(eq.allocated_qty) || 0;
      const rentedToThis = parseInt(eq.rented_qty) || 0;
      const venueToThis = parseInt(eq.venue_qty) || 0;
      const allocatedToOthers = allEquip
        .filter(e2 =>
          (e2.asset_id || '').toUpperCase() === aKey &&
          e2.allocated_reservation_id &&
          sameDateResIds.has(e2.allocated_reservation_id)
        )
        .reduce((s, e2) => s + (parseInt(e2.allocated_qty) || 0), 0);
      const available = Math.max(0, total - allocatedToOthers);
      rows.push({ assetId: eq.asset_id || '—', name: eq.name || '—', needed, buffer, totalReq, total, allocatedToThis, rentedToThis, venueToThis, available });
    });

    // b) Supplement rows (items not yet in the batch for this reservation)
    supplementRows.forEach(nr => {
      const eq = nr.eq;
      const total = parseInt(eq.total_qty || 0);
      const aKey = (eq.asset_id || '').toUpperCase();
      const allocatedToOthers = allEquip
        .filter(e2 =>
          (e2.asset_id || '').toUpperCase() === aKey &&
          e2.allocated_reservation_id &&
          sameDateResIds.has(e2.allocated_reservation_id)
        )
        .reduce((s, e2) => s + (parseInt(e2.allocated_qty) || 0), 0);
      const available = Math.max(0, total - allocatedToOthers);
      const totalReq = nr.needed + nr.buffer;
      rows.push({ assetId: nr.assetId || '—', name: nr.name, needed: nr.needed, buffer: nr.buffer, totalReq, total, allocatedToThis: 0, rentedToThis: 0, venueToThis: 0, available });
    });

    const hasBatchForRes = allEquip.some(e => e.allocated_reservation_id === resId && e.allocation_batch);
    const hasNeeds = rows.some(r => r.totalReq > 0);
    const allAllocated = hasNeeds && rows.every(r => r.totalReq === 0 || (r.allocatedToThis + r.rentedToThis + r.venueToThis) >= r.totalReq);
    const anyShort = rows.some(r => r.totalReq > 0 && (r.available + r.rentedToThis + r.venueToThis) < r.totalReq);
    
    let isModified = false;
    if (hasBatchForRes && typeof _genBatchName === 'function' && typeof _getBatchModificationString === 'function') {
       const batchItem = allEquip.find(e => e.allocated_reservation_id === resId && e.allocation_batch);
       if (batchItem) {
          const expectedBatch = _genBatchName(res);
          if (batchItem.allocation_batch !== expectedBatch) {
             const changeStr = _getBatchModificationString(batchItem.allocation_batch, expectedBatch);
             if (changeStr && changeStr !== 'No significant changes detected.') {
                isModified = true;
             }
          }
       }
    }
    const cardStatus  = (hasBatchForRes || allAllocated) ? 'green' : anyShort ? 'red' : 'yellow';
    const borderColor = cardStatus === 'green' ? 'rgba(45,138,78,0.5)' : cardStatus === 'red' ? 'rgba(192,57,43,0.5)' : 'rgba(196,154,60,0.4)';
    const statusText  = (hasBatchForRes || allAllocated) ? 'Fully Allocated' : anyShort ? 'Short — Cannot Fulfill' : 'Can Be Fulfilled';
    const statusColor = cardStatus === 'green' ? 'var(--green)' : cardStatus === 'red' ? 'var(--red)' : 'var(--gold)';

    const tableRows = rows.map(r => {
      let fulfillable, fColor;
      const totalSecured = r.allocatedToThis + r.rentedToThis + r.venueToThis;
      
      if (totalSecured >= r.totalReq && r.totalReq > 0) {
        if (r.allocatedToThis > 0 && r.venueToThis > 0 && r.rentedToThis > 0) {
          fulfillable = 'Allocated, Rented & Venue'; fColor = 'var(--green)';
        } else if (r.allocatedToThis > 0 && r.venueToThis > 0) {
          fulfillable = 'Allocated & Venue provided'; fColor = 'var(--green)';
        } else if (r.allocatedToThis > 0 && r.rentedToThis > 0) {
          fulfillable = 'Allocated & Rented'; fColor = 'var(--green)';
        } else if (r.rentedToThis > 0) {
          fulfillable = 'Rented'; fColor = 'var(--green)';
        } else if (r.venueToThis > 0) {
          fulfillable = 'Venue Provided'; fColor = 'var(--green)';
        } else {
          fulfillable = 'Allocated'; fColor = 'var(--green)';
        }
      } else if (r.available + r.rentedToThis + r.venueToThis >= r.totalReq) {
        fulfillable = 'Yes';       fColor = 'var(--gold)';
      } else {
        fulfillable = 'Short';     fColor = 'var(--red)';
      }

      let allocatedDisplay = r.allocatedToThis;
      if (r.rentedToThis > 0 && r.venueToThis > 0) allocatedDisplay += ' <span style="color:var(--gold);font-size:10px;">(+' + r.rentedToThis + ' rented, +' + r.venueToThis + ' venue)</span>';
      else if (r.rentedToThis > 0) allocatedDisplay += ' <span style="color:var(--gold);font-size:10px;">(+' + r.rentedToThis + ' rented)</span>';
      else if (r.venueToThis > 0) allocatedDisplay += ' <span style="color:var(--amber);font-size:10px;">(+' + r.venueToThis + ' venue)</span>';

      return '<tr>' +
        '<td style="font-size:11px;padding:6px 10px;color:var(--text);">' + (r.assetId || '—') + '</td>' +
        '<td style="font-size:12px;padding:6px 10px;">' + r.name + '</td>' +
        '<td style="font-size:12px;padding:6px 10px;font-weight:700;">' + r.needed + '</td>' +
        '<td style="font-size:12px;padding:6px 10px;color:var(--amber);">+' + r.buffer + '</td>' +
        '<td style="font-size:12px;padding:6px 10px;font-weight:700;color:var(--cream);">' + r.totalReq + '</td>' +
        '<td style="font-size:12px;padding:6px 10px;">' + allocatedDisplay + '</td>' +
        '<td style="font-size:12px;padding:6px 10px;">' + (resDate ? r.available + ' on ' + resDate : r.total + ' total') + '</td>' +
        '<td style="font-size:12px;padding:6px 10px;font-weight:700;color:' + fColor + ';">' + fulfillable + '</td>' +
      '</tr>';
    }).join('');

    return '<div style="margin-bottom:14px;border:1px solid ' + borderColor + ';border-radius:12px;overflow:hidden;">' +
      '<div style="display:flex;align-items:center;justify-content:space-between;padding:14px 18px;cursor:pointer;" onclick="this.parentElement.querySelector(&quot;.avail-detail&quot;).style.display=this.parentElement.querySelector(&quot;.avail-detail&quot;).style.display===&quot;none&quot;?&quot;block&quot;:&quot;none&quot;">' +
        '<div>' +
          '<div style="display:flex;align-items:center;gap:10px;margin-bottom:4px;">' +
            '<span style="font-size:12px;font-weight:700;color:var(--gold);">' + resId + '</span>' +
            (resDate ? '<span style="font-size:11px;color:var(--text-dim);">' + resDate + '</span>' : '') +
          '</div>' +
          '<div style="font-size:13px;font-weight:600;color:var(--cream);">' + (res.client||'Client') + ' — ' + (res.packageName||res.type||'Event') + '</div>' +
          '<div style="font-size:11px;color:' + statusColor + ';margin-top:3px;font-weight:600;">' + statusText + '</div>' +
          (isModified ? `<div style="font-size:11px;color:var(--gold);margin-top:4px;font-weight:600;">\u26a0\ufe0f Package significantly modified, allocation needs an update</div>` : '') +
        '</div>' +
        '<div style="display:flex;gap:8px;flex-shrink:0;">' +
          '<button class="btn-outline" style="font-size:11px;padding:5px 12px;" onclick="event.stopPropagation();jumpToEqcForBatch(&quot;' + resId + '&quot;)">Allocate</button>' +
        '</div>' +
      '</div>' +
      '<div class="avail-detail" style="display:none;border-top:1px solid var(--border);">' +
        '<div style="padding:10px 18px;">' +
          '<table style="width:100%;border-collapse:collapse;">' +
            '<thead><tr style="border-bottom:1px solid var(--border);">' +
              '<th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Asset ID</th>' +
              '<th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Equipment</th>' +
              '<th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Required</th>' +
              '<th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Buffer</th>' +
              '<th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Total</th>' +
              '<th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Allocated to This</th>' +
              '<th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Available (Date)</th>' +
              '<th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Fulfillable</th>' +
            '</tr></thead>' +
            '<tbody>' + tableRows + '</tbody>' +
          '</table>' +
        '</div>' +
      '</div>' +
    '</div>';

    let finalHtml = '';
    const groupDate = resDate ? new Date(resDate).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' }) : 'Unscheduled';
    if (groupDate !== lastDateGroup && groupDate !== 'Invalid Date') {
      finalHtml += '<div style="font-size:13px; font-weight:700; color:var(--text-dim); margin:20px 0 10px 0; border-bottom:1px solid var(--border); padding-bottom:4px;">' + groupDate + '</div>';
      lastDateGroup = groupDate;
    }
    finalHtml += cardHtml;
    return finalHtml;
  });

  container.innerHTML = cards.join('');
}
window.loadAvailabilityView = loadAvailabilityView;

window.filterAvailability = function(filter, btn) {
  window._availCurrentFilter = filter;
  document.querySelectorAll('#eim-avail-filters .btn-outline').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  loadAvailabilityView();
};

