function openAddEquipmentModal() {
  ['eim-add-id','eim-add-name','eim-add-category','eim-add-type','eim-add-qty','eim-add-unit','eim-add-cost','eim-add-supplier','eim-add-notes'].forEach(id => { const el = document.getElementById(id); if(el) el.value = ''; });
  const _pdEl = document.getElementById('eim-add-purchase-date'); if (_pdEl) _pdEl.value = '';
  const _descEl = document.getElementById('eim-add-description'); if (_descEl) _descEl.value = '';
  document.getElementById('eim-add-overlay').classList.add('on');
  document.getElementById('eim-add-modal').classList.add('open');
}
