const GLOMAR_SUPPLIER = {
  name: 'Glomar P. Legaspi',
  business: 'JM Lenn Party Needs',
  phones: ['09399218454', '09985326226'],
  email: 'jmlenncatering@gmail.com',
  address: '15 Aluminio St. Tugatog Malabon',
  facebook: 'https://facebook.com/jm.lenn.legaspi',
  tagline: 'We bring the seating, you bring the guests!',
  permit: '19.006626'
};

// In-memory cache for rental orders keyed by reservation_id
window._rentalOrderCache = window._rentalOrderCache || {};

// Shortages filter state
let _rntCurrentCat = 'All';

// ---- Main render entry point ----
async function renderRentalHub() {
  const resId = currentEqcReservationId;

  const elNoRes   = document.getElementById('rnt-hub-no-res');
  const elEmpty   = document.getElementById('rnt-hub-empty');
  const elContent = document.getElementById('rnt-hub-content');
  const elPipeline = document.getElementById('rnt-hub-pipeline');
  const elActions  = document.getElementById('rnt-hub-actions');

  if (!elNoRes || !elEmpty || !elContent) return;

  if (!resId) {
    elNoRes.style.display   = '';
    elEmpty.style.display   = 'none';
    elContent.style.display = 'none';
    return;
  }

  elNoRes.style.display = 'none';

  // Ensure currentAllocEvent matches the active reservation for the manifest generator
  if (!currentAllocEvent || currentAllocEvent.id !== resId) {
    currentAllocEvent = RESERVATIONS.find(r => r.id === resId) || null;
  }

  // Ensure the manifest is fresh so we have accurate shortages
  await generateAllocationManifest();
  
  // Build shortages from the deployment manifest
  const shortages = _getRentalHubShortages();

  // Load existing rental order for this reservation from Supabase
  const order = await _loadRentalOrderForRes(resId);

  // Build category filter buttons from unique categories in shortages
  _buildRntFilterButtons(shortages);

  if (!shortages.length && !order) {
    elEmpty.style.display   = '';
    elContent.style.display = 'none';
    return;
  }

  elEmpty.style.display   = 'none';
  elContent.style.display = '';

  // Render Modification Tables
  const modContainer = document.getElementById('rnt-hub-modifications-container');
  if (modContainer) {
    let additionalHtml = '';
    let decreasedHtml = '';
    
    if (order && order.items) {
      let addRows = [];
      let decRows = [];
      
      const combinedItems = new Map();
      order.items.forEach(i => combinedItems.set(i.name, { orderQty: i.qty_needed, shortQty: 0, category: i.category }));
      
      const manifest = _lastGeneratedManifest || [];
      manifest.forEach(s => {
        const trueNeed = Math.max(0, s.finalReq - (s.hasSavedAlloc ? s.allocatedQty : s.inStock));
        if (trueNeed > 0 || combinedItems.has(s.name)) {
          const item = combinedItems.get(s.name) || { orderQty: 0, shortQty: 0, category: s.category };
          item.shortQty = trueNeed;
          combinedItems.set(s.name, item);
        }
      });
      
      combinedItems.forEach((data, name) => {
        if (data.shortQty > data.orderQty) addRows.push({ name, cat: data.category, diff: data.shortQty - data.orderQty, orderQty: data.orderQty, shortQty: data.shortQty });
        else if (data.shortQty < data.orderQty) decRows.push({ name, cat: data.category, diff: data.orderQty - data.shortQty, orderQty: data.orderQty, shortQty: data.shortQty });
      });

      if (addRows.length > 0) {
        additionalHtml = `<div class="panel" style="margin-bottom:20px; border:1px solid var(--gold); background:var(--bg-panel);">
          <div class="panel-hdr" style="background:rgba(196,154,60,0.1);">
            <div>
              <div class="panel-title" style="color:var(--gold);">Additional Rentals</div>
              <div class="panel-sub">You need more equipment than what is currently in your rental order.</div>
            </div>
            <button class="btn-primary" style="font-size:12px; padding:6px 14px;" onclick="updateRentalOrderModification('add', '${resId}')">Include in rental order</button>
          </div>
          <div class="panel-body" style="padding:0;">
            <table class="inv-table">
              <thead><tr><th>Equipment</th><th>Category</th><th>Current Order</th><th>New Required</th><th style="color:var(--gold);">Amount to Add</th></tr></thead>
              <tbody>${addRows.map(r => `<tr><td>${escHtml(r.name)}</td><td><span class="badge pending" style="font-size:10px;">${escHtml(r.cat||'')}</span></td><td>${r.orderQty}</td><td>${r.shortQty}</td><td style="color:var(--gold);font-weight:700;">+${r.diff}</td></tr>`).join('')}</tbody>
            </table>
          </div>
        </div>`;
      }
      if (decRows.length > 0) {
        decreasedHtml = `<div class="panel" style="margin-bottom:20px; border:1px solid var(--red); background:var(--bg-panel);">
          <div class="panel-hdr" style="background:rgba(211,47,47,0.1);">
            <div>
              <div class="panel-title" style="color:var(--red);">Decreased Rental Order</div>
              <div class="panel-sub">You need less equipment than what is currently in your rental order.</div>
            </div>
            <button class="btn-primary" style="font-size:12px; padding:6px 14px;" onclick="updateRentalOrderModification('decrease', '${resId}')">Update</button>
          </div>
          <div class="panel-body" style="padding:0;">
            <table class="inv-table">
              <thead><tr><th>Equipment</th><th>Category</th><th>Current Order</th><th>New Required</th><th style="color:var(--red);">Amount to Decrease</th></tr></thead>
              <tbody>${decRows.map(r => `<tr><td>${escHtml(r.name)}</td><td><span class="badge pending" style="font-size:10px;">${escHtml(r.cat||'')}</span></td><td>${r.orderQty}</td><td>${r.shortQty}</td><td style="color:var(--red);font-weight:700;">-${r.diff}</td></tr>`).join('')}</tbody>
            </table>
          </div>
        </div>`;
      }
    }
    modContainer.innerHTML = additionalHtml + decreasedHtml;
  }

  // Render shortage table (with rental qty injected if order confirmed)
  _renderRntShortTable(shortages, order);

  // Render action buttons
  if (elActions) {
    if (!order) {
      elActions.innerHTML = `<button class="btn-primary" style="font-size:13px;" onclick="createRentalOrder()">Create Rental Order</button>`;
    } else {
      elActions.innerHTML = `
        <button class="btn-reject" style="font-size:13px; margin-right:8px; color:#ffffff;" onclick="deleteRentalOrderForRes('${resId}')">Cancel Order</button>
        <button class="btn-outline" style="font-size:13px; color:#ffffff; border-color:rgba(255,255,255,0.2);" onclick="exportRentalOrderPDF()">Export PDF</button>
      `;
    }
  }

  // Render pipeline
  if (elPipeline) {
    if (order) {
      elPipeline.style.display = '';
      _renderRntPipeline(order);
    } else {
      elPipeline.style.display = 'none';
    }
  }
}

function _getRentalHubShortages() {
  // Pull from the last generated deployment manifest
  const manifest = _lastGeneratedManifest || [];
  return manifest.filter(l => (l.shortfall > 0 || l.unavail));
}

function _buildRntFilterButtons(shortages) {
  const container = document.getElementById('rnt-hub-filters');
  if (!container) return;
  const cats = ['All', ...new Set(shortages.map(s => s.category).filter(Boolean))];
  container.innerHTML = cats.map(c =>
    `<button class="btn-outline${c === _rntCurrentCat ? ' active' : ''}" style="font-size:11px; padding:4px 12px;" onclick="filterRntShortages('${escHtml(c)}', this)">${escHtml(c)}</button>`
  ).join('');
}

function filterRntShortages(cat, btn) {
  _rntCurrentCat = cat;
  document.querySelectorAll('#rnt-hub-filters .btn-outline').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  const shortages = _getRentalHubShortages();
  const order = window._rentalOrderCache[currentEqcReservationId] || null;
  _renderRntShortTable(shortages, order);
}

function _renderRntShortTable(shortages, order) {
  const tbody = document.getElementById('rnt-hub-short-tbody');
  const sub   = document.getElementById('rnt-hub-short-sub');
  if (!tbody) return;

  const filtered = _rntCurrentCat === 'All' ? shortages : shortages.filter(s => s.category === _rntCurrentCat);

  if (sub) sub.textContent = `${shortages.length} equipment line${shortages.length !== 1 ? 's' : ''} cannot be fulfilled from our inventory for this reservation.`;

  if (!filtered.length) {
    tbody.innerHTML = `<tr><td colspan="7" style="text-align:center; padding:20px; color:var(--text-dim);">No shortages in this category.</td></tr>`;
    return;
  }

  tbody.innerHTML = filtered.map(line => {
    // Find rental qty from the order if supplier confirmed
    let rentalQty = 0;
    let itemStatus = 'pending';
    if (order && (order.status === 'supplier_confirmed' || order.status === 'scheduled' || order.status === 'delivered' || order.status === 'completed')) {
      const orderItem = (order.items || []).find(i => i.name === line.name);
      if (orderItem) {
        rentalQty  = orderItem.qty_needed || 0;
        itemStatus = orderItem.item_status || 'confirmed';
      }
    } else if (order) {
      const orderItem = (order.items || []).find(i => i.name === line.name);
      if (orderItem) rentalQty = orderItem.qty_needed || 0;
    }

    const statusBadge = order
      ? `<span class="badge ${itemStatus === 'confirmed' ? 'confirmed' : 'pending'}" style="font-size:10px;">${itemStatus === 'confirmed' ? 'Confirmed' : 'Pending'}</span>`
      : `<span style="font-size:12px; color:var(--text-dim);">—</span>`;

    const rentalCell = rentalQty > 0
      ? `<span style="font-weight:700; color:var(--gold);">${rentalQty}</span>`
      : (order ? `<span style="color:var(--text-dim);">0</span>` : `<span style="color:var(--text-dim);">—</span>`);

    return `<tr>
      <td><div class="item-name">${escHtml(line.name)}</div></td>
      <td><span class="badge pending" style="font-size:10px;">${escHtml(line.category)}</span></td>
      <td style="font-size:13px; font-weight:600;">${line.finalReq}</td>
      <td style="font-size:13px; color:${line.inStock < line.finalReq ? 'var(--red)' : 'var(--text)'};">${line.inStock}</td>
      <td style="font-size:14px; font-weight:700; color:var(--red);">${line.unavail ? 'All' : line.shortfall}</td>
      <td>${rentalCell}</td>
      <td>${statusBadge}</td>
    </tr>`;
  }).join('');
}

const RNT_STATUSES = [
  { key: 'request_sent',       label: 'Request Sent' },
  { key: 'supplier_confirmed', label: 'Supplier Confirmed' },
  { key: 'scheduled',          label: 'Scheduled' },
  { key: 'delivered',          label: 'Delivered' },
  { key: 'completed',          label: 'Completed' }
];

function _renderRntPipeline(order) {
  const bar     = document.getElementById('rnt-status-bar');
  const orderIdEl = document.getElementById('rnt-hub-order-id');
  const itemsCon  = document.getElementById('rnt-hub-order-items-container');
  if (!bar) return;

  if (orderIdEl) orderIdEl.textContent = `Rental Order ${order.rental_order_id}`;

  const currentIdx = RNT_STATUSES.findIndex(s => s.key === order.status);

  bar.innerHTML = RNT_STATUSES.map((step, i) => {
    const isDone    = i <= currentIdx;
    const isNext    = i === currentIdx + 1;
    const bg        = isDone  ? 'var(--gold)'  : 'transparent';
    const color     = isDone  ? '#1a1a0e'      : isNext ? 'var(--gold)' : 'var(--text-dim)';
    const border    = isNext  ? '2px solid var(--gold)' : isDone ? 'none' : '1px solid var(--border)';
    const cursor    = isNext  ? 'pointer'      : 'default';
    const onclick   = isNext  ? `onclick="advanceRentalOrderStatus('${step.key}')"` : '';
    return `<div style="flex:1; padding:12px 8px; text-align:center; background:${bg}; color:${color}; font-size:12px; font-weight:700; cursor:${cursor}; border-right:1px solid var(--border); transition:all 0.2s;" ${onclick}>${escHtml(step.label)}</div>`;
  }).join('');

  // Items table in pipeline
  if (itemsCon) {
    const items = order.items || [];
    if (!items.length) { itemsCon.innerHTML = ''; return; }
    if (window._isEnteringSupplierResponse) {
      const targetLabel = window._targetRentalStatus === 'scheduled' ? 'Scheduled' : window._targetRentalStatus === 'delivered' ? 'Delivered' : 'Supplier Can Provide';
      itemsCon.innerHTML = `
        <div style="font-size:11px; font-weight:800; color:var(--text-dim); text-transform:uppercase; letter-spacing:1px; margin-bottom:10px;">Enter ${targetLabel} Quantity</div>
        <table class="inv-table" style="font-size:12px;">
          <thead><tr><th>Equipment</th><th>Requested</th><th>${targetLabel}</th></tr></thead>
          <tbody>${items.map((it, idx) => {
            const defVal = window._targetRentalStatus === 'delivered' ? (it.qty_scheduled !== undefined ? it.qty_scheduled : it.qty_provided !== undefined ? it.qty_provided : it.qty_needed) : window._targetRentalStatus === 'scheduled' ? (it.qty_provided !== undefined ? it.qty_provided : it.qty_needed) : it.qty_needed;
            return `
            <tr>
              <td>${escHtml(it.name)}</td>
              <td style="font-weight:700;">${it.qty_needed}</td>
              <td>
                <input type="number" id="supp-resp-qty-${idx}" class="input-field" value="${defVal}" min="0" style="width:80px;padding:4px 8px;font-size:12px;" />
              </td>
            </tr>`;
          }).join('')}
          </tbody>
        </table>
        <div style="margin-top:15px; text-align:right;">
          <button class="btn-outline" style="margin-right:10px;" onclick="cancelSupplierResponse()">Cancel</button>
          <button class="btn-primary" onclick="submitSupplierResponse()">Confirm Supplier Response</button>
        </div>`;
    } else {
      const showConfirmedCol = currentIdx >= 1; // 1 is 'supplier_confirmed'
      const showScheduledCol = currentIdx >= 2; // 2 is 'scheduled'
      const showDeliveredCol = currentIdx >= 3; // 3 is 'delivered'
      
      itemsCon.innerHTML = `
        <div style="font-size:11px; font-weight:800; color:var(--text-dim); text-transform:uppercase; letter-spacing:1px; margin-bottom:10px;">Order Items</div>
        <table class="inv-table" style="font-size:12px;">
          <thead>
            <tr>
              <th>Equipment</th>
              <th>Category</th>
              <th>Qty Needed</th>
              ${showConfirmedCol ? '<th>Confirmed</th>' : ''}
              ${showScheduledCol ? '<th>Scheduled</th>' : ''}
              ${showDeliveredCol ? '<th>Delivered</th>' : ''}
              <th>Status</th>
            </tr>
          </thead>
          <tbody>${items.map(it => {
            let badgeClass = 'pending';
            let badgeText = 'Pending';
            if (it.item_status === 'confirmed' || it.item_status === 'completed') { badgeClass = 'confirmed'; badgeText = it.item_status === 'completed' ? 'Completed' : 'Confirmed'; }
            else if (it.item_status === 'partially' || it.item_status === 'partially_resolved') { badgeClass = 'warning'; badgeText = 'Partially'; }
            else if (it.item_status === 'unavailable' || it.item_status === 'unavailable_resolved') { badgeClass = 'critical'; badgeText = 'Unavailable'; }
            
            if (it.item_status && it.item_status.includes('resolved')) badgeText += ' (Resolved)';

            return `
            <tr>
              <td>${escHtml(it.name)}</td>
              <td><span class="badge pending" style="font-size:10px;">${escHtml(it.category || '')}</span></td>
              <td style="font-weight:700; color:var(--gold);">${it.qty_needed}</td>
              ${showConfirmedCol ? `<td style="font-weight:700; color:${it.qty_provided < it.qty_needed ? 'var(--amber)' : 'var(--cream)'};">${it.qty_provided !== undefined ? it.qty_provided : (it.item_status === 'confirmed' || it.item_status === 'completed' ? it.qty_needed : 0)}</td>` : ''}
              ${showScheduledCol ? `<td style="font-weight:700; color:${(it.qty_scheduled || 0) < (it.qty_provided || it.qty_needed) ? 'var(--amber)' : 'var(--cream)'};">${it.qty_scheduled !== undefined ? it.qty_scheduled : '-'}</td>` : ''}
              ${showDeliveredCol ? `<td style="font-weight:700; color:${(it.qty_delivered || 0) < (it.qty_scheduled || it.qty_provided || it.qty_needed) ? 'var(--amber)' : 'var(--cream)'};">${it.qty_delivered !== undefined ? it.qty_delivered : '-'}</td>` : ''}
              <td><span class="badge ${badgeClass}" style="font-size:10px;white-space:nowrap;">${badgeText}</span></td>
            </tr>`;
          }).join('')}
          </tbody>
        </table>`;

      // Render Equipment Shopping List if there are unresolved items
      const unresolvedItems = items.filter(it => it.item_status === 'partially' || it.item_status === 'unavailable');
      if (unresolvedItems.length > 0) {
        itemsCon.innerHTML += `
          <div style="margin-top:25px; border-top:1px dashed var(--border); padding-top:15px;">
            <div style="font-size:11px; font-weight:800; color:var(--amber); text-transform:uppercase; letter-spacing:1px; margin-bottom:10px;">Equipment Shopping List</div>
            <div style="font-size:11px; color:var(--text-dim); margin-bottom:10px;">These items are missing and need to be bought. Once bought, they will be added to the inventory.</div>
            <table class="inv-table" style="font-size:12px;">
              <thead>
                <tr>
                  <th>Equipment</th>
                  <th>Quantity Still Needed</th>
                  <th style="width:100px;">Action</th>
                </tr>
              </thead>
              <tbody>${unresolvedItems.map(it => {
                const qtyStillNeeded = Math.max(0, it.qty_needed - (it.qty_provided || 0));
                return `
                <tr>
                  <td>${escHtml(it.name)}</td>
                  <td style="font-weight:700; color:var(--red);">${qtyStillNeeded}</td>
                  <td>
                    <button class="btn-primary" style="font-size:11px; padding:4px 10px;" onclick="buyShoppingListItem('${order.id}', '${escHtml(it.name).replace(/'/g, "\\'")}', ${qtyStillNeeded})">Bought</button>
                  </td>
                </tr>`;
              }).join('')}
              </tbody>
            </table>
          </div>
        `;
      }
    }
  }
}

// ---- Load/save rental order from Supabase ----
async function _loadRentalOrderForRes(resId) {
  if (!resId) return null;
  if (window._rentalOrderCache[resId] !== undefined) return window._rentalOrderCache[resId];

  const sb = window.supabaseClient;
  if (!sb) return null;
  try {
    const { data, error } = await sb.from('rental_orders').select('*').eq('reservation_id', resId).order('created_at', { ascending: false }).limit(1);
    if (error || !data || !data.length) {
      window._rentalOrderCache[resId] = null;
      return null;
    }
    window._rentalOrderCache[resId] = data[0];
    return data[0];
  } catch(e) {
    console.warn('[RentalHub] Load failed:', e);
    return null;
  }
}

function _generateRentalOrderId() {
  const d = new Date();
  const dateStr = d.getFullYear() + String(d.getMonth()+1).padStart(2,'0') + String(d.getDate()).padStart(2,'0');
  const seq = String(Math.floor(Math.random() * 900) + 100);
  return `RO-${dateStr}-${seq}`;
}

window.updateRentalOrderModification = async function(action, resId) {
  const sb = window.supabaseClient;
  if (!sb) return;
  const order = window._rentalOrderCache[resId];
  if (!order) return;

  const shortages = _getRentalHubShortages();
  let updatedItems = JSON.parse(JSON.stringify(order.items || []));
  let changed = false;

  if (action === 'add') {
    shortages.forEach(s => {
      let existingItem = updatedItems.find(i => i.name === s.name);
      if (!existingItem) {
        updatedItems.push({ name: s.name, category: s.category, qty_needed: s.shortfall, item_status: 'pending' });
        changed = true;
      } else if (s.shortfall > existingItem.qty_needed) {
        existingItem.qty_needed = s.shortfall;
        changed = true;
      }
    });
  } else if (action === 'decrease') {
    updatedItems.forEach(i => {
      const s = shortages.find(sh => sh.name === i.name);
      if (s && s.shortfall < i.qty_needed) {
        i.qty_needed = s.shortfall;
        changed = true;
      }
    });
    const lenBefore = updatedItems.length;
    updatedItems = updatedItems.filter(i => {
      const s = shortages.find(sh => sh.name === i.name);
      return (s && s.shortfall > 0);
    });
    if (updatedItems.length !== lenBefore) changed = true;
  }

  if (changed) {
    const btn = event.target;
    const oldText = btn.textContent;
    btn.textContent = 'Updating...';
    btn.disabled = true;
    
    const { error } = await sb.from('rental_orders').update({ items: updatedItems }).eq('id', order.id);
    if (error) {
      showToast('Failed to update rental order.', 'error');
      btn.textContent = oldText;
      btn.disabled = false;
    } else {
      showToast('Rental order successfully updated!');
      window._rentalOrderCache[resId].items = updatedItems;
      renderRentalHub();
    }
  }
};

function createRentalOrder() {
  const resId = currentEqcReservationId;
  if (!resId) { showToast('No reservation selected.', 'error'); return; }

  const shortages = _getRentalHubShortages();
  if (!shortages.length) { showToast('No shortages to create a rental order for.', 'error'); return; }

  const modalId = 'ro-confirm-modal-' + Date.now();
  const modalHTML = `
    <div id="${modalId}" style="position:fixed; top:0; left:0; width:100vw; height:100vh; background:rgba(0,0,0,0.6); z-index:9999; display:flex; align-items:center; justify-content:center; backdrop-filter:blur(4px);">
      <div style="background:var(--bg-panel); border:1px solid var(--border); border-radius:12px; padding:30px; width:420px; box-shadow:0 15px 30px rgba(0,0,0,0.5); text-align:center;">
        <h2 style="margin-bottom:10px; font-size:18px; color:var(--text);">Confirm Rental Order</h2>
        <p style="font-size:13px; color:var(--text-dim); margin-bottom:20px; line-height:1.5;">
          Are you sure you want to make a rental order now?<br><br>
          <span style="color:var(--amber);">Warning:</span> After doing this, it will be tedious to modify the reservation beyond this point as it will indirectly cause the rental orders to change depending on what was modified.
        </p>
        <div style="display:flex; justify-content:center; gap:12px;">
          <button class="btn-outline" onclick="document.getElementById('${modalId}').remove()">No, Cancel</button>
          <button class="btn-primary" onclick="document.getElementById('${modalId}').remove(); _executeCreateRentalOrder()">Yes, Proceed</button>
        </div>
      </div>
    </div>
  `;
  document.body.insertAdjacentHTML('beforeend', modalHTML);
}

async function _executeCreateRentalOrder() {
  const resId = currentEqcReservationId;
  if (!resId) { showToast('No reservation selected.', 'error'); return; }

  const ev = (RESERVATIONS || []).find(r => r.id === resId);
  const shortages = _getRentalHubShortages();
  if (!shortages.length) { showToast('No shortages to create a rental order for.', 'error'); return; }

  const sb = window.supabaseClient;
  if (!sb) { showToast('Supabase not available.', 'error'); return; }

  const items = shortages.map(line => ({
    name: line.name,
    category: line.category || '',
    qty_needed: line.unavail ? line.finalReq : line.shortfall,
    item_status: 'pending'
  }));

  const payload = {
    rental_order_id:  _generateRentalOrderId(),
    reservation_id:   resId,
    reservation_name: ev ? (ev.client || ev.packageName || ev.name || resId) : resId,
    supplier_name:    GLOMAR_SUPPLIER.name,
    status:           'request_sent',
    items:            items
  };

  try {
    const { data, error } = await sb.from('rental_orders').insert(payload).select().single();
    if (error) throw error;
    window._rentalOrderCache[resId] = data;
    showToast(`Rental order ${data.rental_order_id} created.`);
    renderRentalHub();
  } catch(e) {
    console.error('[RentalHub] Create order failed:', e);
    showToast('Failed to create rental order. Check console.', 'error');
  }
}
window._executeCreateRentalOrder = _executeCreateRentalOrder;
window.createRentalOrder = createRentalOrder;

async function advanceRentalOrderStatus(newStatus) {
  const resId = currentEqcReservationId;
  if (!resId) return;
  const order = window._rentalOrderCache[resId];
  if (!order) return;

  const sb = window.supabaseClient;
  if (!sb) { showToast('Supabase not available.', 'error'); return; }

  // Intercept 'supplier_confirmed', 'scheduled', 'delivered' to show response UI instead of auto-confirming
  if (['supplier_confirmed', 'scheduled', 'delivered'].includes(newStatus)) {
    if (!window._isEnteringSupplierResponse) {
      window._isEnteringSupplierResponse = true;
      window._targetRentalStatus = newStatus;
      renderRentalHub();
      return;
    }
  }

  // The submitSupplierResponse function handles updating the items and then calls this.
  let updatedItems = order.items;
  if (newStatus === 'completed') {
    updatedItems = updatedItems.map(it => ({ ...it, item_status: 'completed' }));
  }


  try {
    const { data, error } = await sb.from('rental_orders')
      .update({ status: newStatus, items: updatedItems, updated_at: new Date().toISOString() })
      .eq('id', order.id)
      .select().single();
    if (error) throw error;
    window._rentalOrderCache[resId] = data;
    showToast(`Status updated to: ${RNT_STATUSES.find(s => s.key === newStatus)?.label || newStatus}`);

    // If supplier confirmed, push rental qty into the deployment manifest
    if (newStatus === 'supplier_confirmed') {
      applyRentalQtyToManifest(resId, data);
    }

    renderRentalHub();
  } catch(e) {
    console.error('[RentalHub] Status advance failed:', e);
    showToast('Failed to update order status. Check console.', 'error');
  }
}

function cancelSupplierResponse() {
  window._isEnteringSupplierResponse = false;
  window._targetRentalStatus = null;
  renderRentalHub();
}
window.cancelSupplierResponse = cancelSupplierResponse;

async function submitSupplierResponse() {
  const resId = currentEqcReservationId;
  if (!resId) return;
  const order = window._rentalOrderCache[resId];
  if (!order || !order.items) return;

  const sb = window.supabaseClient;
  if (!sb) { showToast('Supabase not available.', 'error'); return; }

  let updatedItems = [...order.items];
  for (let i = 0; i < updatedItems.length; i++) {
    const el = document.getElementById(`supp-resp-qty-${i}`);
    if (el) {
      let provided = parseInt(el.value, 10);
      if (isNaN(provided) || provided < 0) provided = 0;
      
      const needed = updatedItems[i].qty_needed || 0;
      
      if (window._targetRentalStatus === 'scheduled') {
        updatedItems[i].qty_scheduled = provided;
      } else if (window._targetRentalStatus === 'delivered') {
        updatedItems[i].qty_delivered = provided;
      } else {
        updatedItems[i].qty_provided = provided;
      }
      
      // Update item_status for confirmed step
      if (!window._targetRentalStatus || window._targetRentalStatus === 'supplier_confirmed') {
        if (provided === needed) {
          updatedItems[i].item_status = 'confirmed';
        } else if (provided === 0) {
          updatedItems[i].item_status = 'unavailable';
        } else {
          updatedItems[i].item_status = 'partially';
        }
      }
    }
  }

  try {
    const { data, error } = await sb.from('rental_orders')
      .update({ items: updatedItems })
      .eq('id', order.id)
      .select().single();
      
    if (error) throw error;
    
    // Update local cache
    window._rentalOrderCache[resId] = data;
    
    // Disable the entry mode
    window._isEnteringSupplierResponse = false;
    
    // Advance to target status
    const target = window._targetRentalStatus || 'supplier_confirmed';
    window._targetRentalStatus = null;
    await advanceRentalOrderStatus(target);
  } catch (e) {
    console.error('[RentalHub] Submit supplier response failed:', e);
    showToast('Failed to save supplier response.', 'error');
  }
}
window.submitSupplierResponse = submitSupplierResponse;

async function buyShoppingListItem(orderId, itemName, qtyToBuy) {
  const sb = window.supabaseClient;
  if (!sb) { showToast('Supabase not available.', 'error'); return; }

  try {
    // 1. Fetch inventory item
    let { data: invData, error: invError } = await sb.from('equipment_inventory').select('*').eq('name', itemName).single();
    if (invError || !invData) {
      console.error('[RentalHub] Failed to fetch equipment item:', invError);
      showToast('Failed to find inventory item.', 'error');
      return;
    }

    // 2. Increment stock quantity
    const newStock = (parseInt(invData.quantity) || 0) + qtyToBuy;
    let { error: updateInvError } = await sb.from('equipment_inventory').update({ quantity: newStock }).eq('id', invData.id);
    if (updateInvError) {
      console.error('[RentalHub] Failed to update inventory:', updateInvError);
      showToast('Failed to update inventory.', 'error');
      return;
    }

    // 3. Update rental order item status
    const resId = currentEqcReservationId;
    const order = window._rentalOrderCache[resId];
    if (!order || !order.items) return;

    let updatedItems = [...order.items];
    const itemIndex = updatedItems.findIndex(it => it.name === itemName);
    if (itemIndex > -1) {
      const status = updatedItems[itemIndex].item_status;
      if (status === 'partially') {
        updatedItems[itemIndex].item_status = 'partially_resolved';
      } else if (status === 'unavailable') {
        updatedItems[itemIndex].item_status = 'unavailable_resolved';
      }
    }

    let { data: updateOrderData, error: updateOrderError } = await sb.from('rental_orders')
      .update({ items: updatedItems })
      .eq('id', orderId)
      .select().single();

    if (updateOrderError) throw updateOrderError;

    // Update local cache
    window._rentalOrderCache[resId] = updateOrderData;
    showToast(`Bought ${qtyToBuy} ${itemName}. Added to inventory.`, 'success');
    
    // Re-render
    renderRentalHub();
  } catch (e) {
    console.error('[RentalHub] Buy shopping list item failed:', e);
    showToast('Failed to complete purchase action.', 'error');
  }
}
window.buyShoppingListItem = buyShoppingListItem;

function applyRentalQtyToManifest(resId, order) {
  if (!order || !_lastGeneratedManifest) return;
  const items = order.items || [];
  _lastGeneratedManifest.forEach(line => {
    const orderItem = items.find(it => it.name === line.name);
    if (orderItem) {
      line.rentalQty = orderItem.qty_provided !== undefined ? orderItem.qty_provided : (orderItem.qty_needed || 0);
      // Recalculate shortfall considering rentals
      line.shortfall = Math.max(0, line.finalReq - line.inStock - line.rentalQty);
    }
  });
  // Re-evaluate aggregate counts
  const shortCount = _lastGeneratedManifest.filter(l => l.shortfall > 0 || l.unavail).length;
  const badge = document.getElementById('alloc-manifest-badge');
  if (badge) {
    badge.textContent = shortCount > 0 ? `${shortCount} SHORTAGE${shortCount > 1 ? 'S' : ''}` : 'FULLY COVERED';
  }
  // Re-render manifest table if it's visible
  if (document.getElementById('alloc-manifest-tbody')) {
    const mode = window._allocMode;
    if (typeof _renderManifestWithAllocCol === 'function') _renderManifestWithAllocCol(mode);
  }
  // Update status banner
  const banner = document.getElementById('alloc-status-banner');
  if (banner && banner.style.display !== 'none') {
    const pax = currentAllocEvent ? (currentAllocEvent.pax || currentAllocEvent.guests || 0) : 0;
    if (shortCount === 0) {
      banner.innerHTML = `<div style="padding:14px 20px;background:rgba(45,138,78,0.12);border:1px solid var(--green);border-radius:12px;display:flex;align-items:center;gap:14px;margin-bottom:4px;">
        <div><div style="font-size:14px;font-weight:700;color:var(--green);">All Equipment Fully Covered</div>
        <div style="font-size:12px;color:var(--text-dim);">Inventory and rentals satisfy all requirements. Ready to deploy.</div></div></div>`;
    }
  }
  // Update shortage panel visibility
  const shortPanel = document.getElementById('alloc-shortage-panel');
  if (shortPanel) shortPanel.style.display = shortCount > 0 ? 'block' : 'none';
}

// Auto-load rental order and apply to manifest when reservation is selected
async function checkAndApplyRentalQty(resId) {
  if (!resId) return;
  const order = await _loadRentalOrderForRes(resId);
  if (order && (order.status === 'supplier_confirmed' || order.status === 'scheduled' || order.status === 'delivered' || order.status === 'completed')) {
    applyRentalQtyToManifest(resId, order);
  }
}

function exportRentalOrderPDF() {
  const resId = currentEqcReservationId;
  if (!resId) { showToast('No reservation selected.', 'error'); return; }
  const order = window._rentalOrderCache[resId];
  if (!order) { showToast('No rental order found for this reservation.', 'error'); return; }

  const formatTimeAMPM = (t) => {
    if (!t) return '';
    const parts = t.split(':');
    if (parts.length < 2) return t;
    const hNum = parseInt(parts[0]);
    const ampm = hNum >= 12 ? 'PM' : 'AM';
    const h12 = hNum % 12 || 12;
    return `${h12}:${parts[1]} ${ampm}`;
  };

  const ev = (RESERVATIONS || []).find(r => r.id === resId);
  const evName = ev ? (ev.client || ev.packageName || ev.name || resId) : resId;
  const evDate = ev ? (ev.date || ev.eventDate || '') : '';
  const timeStr = ev ? ((ev.eventTimeStart || ev.startTime ? formatTimeAMPM(ev.eventTimeStart || ev.startTime) : '') + (ev.eventTimeEnd || ev.endTime ? ' — ' + formatTimeAMPM(ev.eventTimeEnd || ev.endTime) : '')) : '';
  const venueStr = ev ? (ev.venue || ev.venueAddress || ev.location || 'Venue TBD') : 'Venue TBD';

  const rows = (order.items || []).map(it =>
    `<tr><td>${escHtml(it.name)}</td><td>${escHtml(it.category || '')}</td><td style="text-align:center;font-weight:700;">${it.qty_needed}</td></tr>`
  ).join('');

  const w = window.open('', '_blank');
  w.document.write(`<html><head><title>Rental Order ${escHtml(order.rental_order_id)}</title>
  <style>
    body{font-family:Arial,sans-serif;padding:32px;color:#222;}
    h2{margin-bottom:4px;}
    .sup{background:#f9f6ee;border:1px solid #c4aa3c;border-radius:8px;padding:16px;margin:16px 0;}
    table{width:100%;border-collapse:collapse;margin-top:16px;}
    th,td{border:1px solid #ddd;padding:10px;text-align:left;}
    th{background:#f4f4f4;font-weight:700;}
    .badge{display:inline-block;padding:2px 8px;border-radius:4px;font-size:11px;font-weight:700;background:#eaeaea;}
  </style></head><body>
  <h2>Rental Order ${escHtml(order.rental_order_id)}</h2>
  <p><strong>Reservation:</strong> ${escHtml(evName)} &mdash; ${escHtml(evDate)}</p>
  <p><strong>Time:</strong> ${escHtml(timeStr)}</p>
  <p><strong>Venue:</strong> ${escHtml(venueStr)}</p>
  <p><strong>Status:</strong> <span class="badge">${escHtml(order.status.replace(/_/g,' ').toUpperCase())}</span></p>
  <div class="sup">
    <strong style="font-size:16px;">${escHtml(GLOMAR_SUPPLIER.name)}</strong> &mdash; ${escHtml(GLOMAR_SUPPLIER.business)}<br>
    Phone: ${GLOMAR_SUPPLIER.phones.join(' / ')}<br>
    Email: ${escHtml(GLOMAR_SUPPLIER.email)}<br>
    Address: ${escHtml(GLOMAR_SUPPLIER.address)}<br>
    Facebook: ${escHtml(GLOMAR_SUPPLIER.facebook)}<br>
    Business Permit No.: ${escHtml(GLOMAR_SUPPLIER.permit)}
  </div>
  <table><thead><tr><th>Equipment</th><th>Category</th><th style="text-align:center;">Qty Needed</th></tr></thead>
  <tbody>${rows}</tbody></table>
  </body></html>`);
  w.document.close();
  w.print();
}

