// ---- Called by saveAllocAssignment to also save rental items ----
async function saveRentalAllocItems(ev, batchName) {
  const resId = ev ? ev.id : null;
  if (!resId) return;
  const order = window._rentalOrderCache[resId];
  if (!order || order.status === 'request_sent') return; // only save if at least request_sent (they created an order)

  const sb = window.supabaseClient;
  if (!sb) return;
  const evLabel = ev.packageName || ev.client || ev.name || ev.id;

  for (const item of (order.items || [])) {
    try {
      const { error: rErr } = await sb.from('allocation_history').insert({
        equipment_id:     null,
        asset_id:         null,
        equipment_name:   item.name,
        allocation_batch: batchName,
        reservation_id:   resId,
        reservation_name: evLabel,
        allocation_date:  ev.date || ev.eventDate || null,
        allocated_qty:    item.qty_needed,
        is_rental:        true
      });
      if (rErr) console.warn('[RentalAlloc] Insert failed:', rErr);
    } catch (e) { console.warn('[RentalAlloc] Insert failed:', e); }
  }
}

