// State
// =====================================================================
// EQUIPMENT CYCLE - GLOBAL STATE & DROPDOWN
// =====================================================================
let currentEqcReservationId = null;
let currentAllocEvent = null;

window.onEqcReservationChange = function () {
  const sel = document.getElementById('eqc-reservation-select');
  const newResId = sel ? sel.value : null;

  // Clear rental cache for old reservation so it re-fetches on demand
  if (currentEqcReservationId && currentEqcReservationId !== newResId) {
    // Keep cache but mark as stale by deleting — will re-fetch from Supabase
    delete window._rentalOrderCache[currentEqcReservationId];
  }
  currentEqcReservationId = newResId;

  // Re-render the active eq-cycle tab
  const activeTab = document.querySelector('.eq-cycle-tab.active');
  if (activeTab) {
    if (activeTab.id === 'eqc-tab-allocation' && typeof renderAllocationSection === 'function') renderAllocationSection();
    if (activeTab.id === 'eqc-tab-scheduling' && typeof renderSchedulingSection === 'function') renderSchedulingSection();
    if (activeTab.id === 'eqc-tab-lifecycle' && typeof renderLifecycleSection === 'function') renderLifecycleSection();
    if (activeTab.id === 'eqc-tab-issues' && typeof renderEquipIssues === 'function') renderEquipIssues();
    if (activeTab.id === 'eqc-tab-rentals') renderRentalHub();
  }
};

window.populateEqcDropdown = function () {
  const sel = document.getElementById('eqc-reservation-select');
  if (!sel) return;
  const confirmed = RESERVATIONS.filter(r => r.status === 'confirmed');

  sel.innerHTML = '<option value="">Choose a confirmed reservation...</option>' +
    confirmed.map(r => {
      const evName = r.packageName || r.name || r.client || '(Unnamed)';
      const evDate = r.date || r.eventDate || '';
      const evPax  = r.pax || r.guests || '';
      return `<option value="${r.id}">${evName}${evDate ? ' : ' + evDate : ''}${evPax ? ' (' + evPax + ' pax)' : ''}</option>`;
    }).join('');

  if (currentEqcReservationId && confirmed.find(r => r.id === currentEqcReservationId)) {
    sel.value = currentEqcReservationId;
  } else {
    currentEqcReservationId = null;
    sel.value = "";
  }
};

function renderAllocationSection() {
  if (typeof populateEqcDropdown === 'function') populateEqcDropdown();

  if (currentEqcReservationId) {
    const still = RESERVATIONS.find(r => r.id === currentEqcReservationId);
    if (still) {
      currentAllocEvent = still;
      _showEquipmentNeededList(still);
      _hideAllocResults();
      cancelAllocMode(); // Reset any active allocation mode
      ['venue-tables', 'venue-chairs', 'venue-chafing', 'venue-dispensers',
        'venue-plates', 'venue-forks', 'venue-spoons', 'venue-knives', 'venue-glasses'].forEach(id => {
          const el = document.getElementById(id); if (el) el.value = 0;
        });
      const otherEl = document.getElementById('venue-other'); if (otherEl) otherEl.value = '';
      const si = document.getElementById('venue-save-status'); if (si) si.style.display = 'none';
      const ai = document.getElementById('venue-autofill-status'); if (ai) { ai.textContent = ''; ai.style.display = 'none'; }
      loadVenueEquipment(still.id);
      // Auto-generate manifest after a short delay to allow async equipment fetch to complete
      setTimeout(() => { if (currentAllocEvent) generateAllocationManifest(); }, 800);
    } else {
      currentAllocEvent = null;
      _hideAllocResults();
      _clearEquipmentNeededList();
    }
  } else {
    currentAllocEvent = null;
    _hideAllocResults();
    _clearEquipmentNeededList();
  }
}

window.findAssetForRule = function(rule) {
  if (!EIM_ASSETS || !EIM_ASSETS.length) return null;
  let asset = null;

  // 1. Exact asset_id / supabaseId match (highest confidence)
  if (rule.assetId) {
    asset = EIM_ASSETS.find(a => a.id === rule.assetId || a.supabaseId === rule.assetId || a.asset_id === rule.assetId || a.batchTrackingId === rule.assetId);
    if (asset) return asset;
  }

  const rName = (rule.name || '').toLowerCase().trim();
  if (!rName) return null;

  // 2. Exact name match (case-insensitive)
  asset = EIM_ASSETS.find(a => a.name && a.name.toLowerCase().trim() === rName);
  if (asset) return asset;

  // 3. Specific well-known fuzzy matches — only fire when both sides contain the key phrase
  //    (ordered from most-specific to least-specific to avoid cross-asset contamination)
  for (const a of EIM_ASSETS) {
    if (!a.name) continue;
    const aName = a.name.toLowerCase().trim();

    // Specific compound names must match each other fully before broad keywords
    if (rName.includes('chafing dish lid') && aName.includes('chafing dish lid')) return a;
    if (rName.includes('chafing dish') && !rName.includes('lid') && aName.includes('chafing dish') && !aName.includes('lid')) return a;
    if (rName.includes('food pan') && aName.includes('food pan')) return a;
    if (rName.includes('serving tray') && aName.includes('serving tray')) return a;
    if (rName.includes('serving fork') && aName.includes('serving fork')) return a;
    if (rName.includes('serving spoon') && aName.includes('serving spoon')) return a;
    if (rName.includes('serving tong') && aName.includes('serving tong')) return a;
    if (rName.includes('round banquet table') && aName.includes('round banquet table')) return a;
    if (rName.includes('tiffany') && aName.includes('tiffany')) return a;
    if (rName.includes('dinner plate') && aName.includes('dinner plate')) return a;
    if (rName.includes('dinner knife') && aName.includes('dinner knife')) return a;
    if (rName.includes('monoblock') && aName.includes('monoblock')) return a;
    if (rName.includes('dispenser') && aName.includes('dispenser')) return a;
    if (rName.includes('tablecloth') && (aName.includes('table cloth') || aName.includes('tablecloth'))) return a;
    if (rName.includes('speaker') && aName.includes('speaker')) return a;
    if (rName.includes('uplight') && (aName.includes('lighting') || aName.includes('uplight'))) return a;
  }

  // 4. Generic substring fallback (only when name is long enough to avoid false matches)
  for (const a of EIM_ASSETS) {
    if (!a.name) continue;
    const aName = a.name.toLowerCase().trim();
    if (rName.length > 5 && aName === rName) return a; // already handled above, safety
    if (rName.length > 7 && aName.includes(rName)) return a;
    if (aName.length > 7 && rName.includes(aName)) return a;
  }

  return null;
}

async function _showEquipmentNeededList(ev) {
  const container = document.getElementById('alloc-equipment-needed-list');
  if (!container) return;

  const pax = parseInt(ev.pax) || 0;
  container.innerHTML = '<div style="text-align:center; padding:20px; color:var(--text-dim); font-size:12px;">Loading equipment list...</div>';

  let riRows = [];
  try {
    const sb = window.supabaseClient;
    if (sb) {
      const { data, error } = await sb
        .from('reservation_items')
        .select('item_id, name, cat, is_free')
        .eq('reservation_id', ev.id);
      if (!error && data) riRows = data;
    }
  } catch (e) {
    console.warn('[EqcNeeded] reservation_items fetch failed:', e);
  }

  let menuItemCount = 1;
  if (riRows.length > 0) {
    menuItemCount = riRows.filter(r => r.cat === 'food').length || 1;
  } else if (ev.packageItems && typeof CAT !== 'undefined') {
    menuItemCount = ev.packageItems.map(n => CAT.find(c => c.name === (typeof n === 'string' ? n : n.name))).filter(i => i && i.cat === 'food').length || 1;
  }

  function _allocLabel(rule) {
    if (rule === 'per_pax')      return 'Per Pax';
    if (rule === 'per_5_pax')    return 'Per 5 Pax';
    if (rule === 'per_8_pax')    return 'Per 8 Pax';
    if (rule === 'per_10_pax')   return 'Per 10 Pax';
    if (rule === 'per_table')    return 'Per Table';
    if (rule === 'per_unit')     return 'Per Unit';
    if (rule === 'per_menu_item') return 'Per Menu Item';
    return 'Fixed';
  }

  function _calcQty(rule, pax, menuItemCount) {
    if (rule === 'per_pax')      return pax;
    if (rule === 'per_5_pax')    return Math.ceil(pax / 5);
    if (rule === 'per_8_pax')    return Math.ceil(pax / 8);
    if (rule === 'per_10_pax')   return Math.ceil(pax / 10);
    if (rule === 'per_table')    return Math.ceil(pax / 8);
    if (rule === 'per_menu_item') return menuItemCount;
    return 1; 
  }

  const seen = new Set();
  const needed = [];

  const processItem = (itemName, itemId) => {
    const key = (itemName || '').toLowerCase().trim();
    if (!key || seen.has(key)) return;
    seen.add(key);

    let asset = null;
    if (itemId && EIM_ASSETS && EIM_ASSETS.length) {
      const sbId = itemId.replace(/^eq-sb-/, '');
      asset = EIM_ASSETS.find(a => a.supabaseId === sbId);
    }
    if (!asset) {
      asset = window.findAssetForRule({ name: itemName });
    }
    if (!asset) return;

    const rule     = (asset.allocationRule || 'fixed').toLowerCase();
    const qty      = _calcQty(rule, pax, menuItemCount);
    const inStock  = asset.availableQty !== undefined ? asset.availableQty : (asset.quantity || 0);
    const sufficient = inStock >= qty;

    needed.push({
      displayName:  asset.name,
      displayId:    asset.id || '',
      allocLabel:   _allocLabel(rule),
      qty,
      inStock,
      sufficient
    });
  };

  if (riRows.length > 0) {
    riRows.filter(r => r.cat === 'equipment').forEach(item => processItem(item.name, item.item_id));
  } else if (ev.packageItems && ev.packageItems.length) {
    ev.packageItems.forEach(itemStr => {
      const name = typeof itemStr === 'string' ? itemStr : (itemStr.name || '');
      processItem(name, null);
    });
  }

  if (needed.length === 0) {
    container.innerHTML = '<div style="text-align:center; padding:20px; color:var(--text-dim); font-size:12px;">No equipment items found for this reservation.</div>';
    return;
  }

  container.innerHTML = needed.map(item => {
    const stockColor = item.sufficient ? 'var(--green)' : 'var(--red)';
    const stockLabel = item.inStock + ' in stock';
    const qtyColor   = item.sufficient ? 'var(--gold)' : 'var(--red)';
    const name       = typeof escHtml === 'function' ? escHtml(item.displayName) : item.displayName;
    return '<div style="display:flex; justify-content:space-between; align-items:center; padding:10px 14px; background:rgba(255,255,255,0.02); border:1px solid rgba(255,255,255,0.05); border-radius:8px; margin-bottom:4px;">'
      + '<div>'
      + '<div style="font-size:12px; font-weight:600; color:var(--cream);">' + name + '</div>'
      + '<div style="font-size:10px; color:var(--text-dim); margin-top:2px;">' + (item.displayId || '') + ' &nbsp;&#183;&nbsp; ' + item.allocLabel + ' &nbsp;&#183;&nbsp; <span style=\'color:' + stockColor + ';\' >' + stockLabel + '</span></div>'
      + '</div>'
      + '<div style="font-size:16px; font-weight:800; color:' + qtyColor + ';">' + item.qty + '</div>'
      + '</div>';
  }).join('');
}

function _clearEquipmentNeededList() {
  const container = document.getElementById('alloc-equipment-needed-list');
  if (container) {
    container.innerHTML = '<div style="text-align:center; padding:20px; color:var(--text-dim); font-size:12px;">Select an active reservation from the top dropdown to view required equipment.</div>';
  }
}

function _hideAllocResults() {
  ['alloc-manifest-panel', 'alloc-shortage-panel', 'alloc-status-banner'].forEach(id => {
    const el = document.getElementById(id); if (el) el.style.display = 'none';
  });
  const empty = document.getElementById('alloc-empty-state');
  if (empty) empty.style.display = currentAllocEvent ? 'none' : 'block';
}

async function generateAllocationManifest() {
  if (!currentAllocEvent) { alert('Please select an event first.'); return; }
  const ev = currentAllocEvent;
  const pax = parseInt(ev.pax) || 0;

  let otherAllocs = [];
  let thisAlloc = [];
  let latestBatchName = null;
  if (window.supabaseClient && typeof RESERVATIONS !== 'undefined') {
    try {
      const formatResDate = (dStr) => {
        if (!dStr) return null;
        const d = new Date(dStr);
        if (!isNaN(d.getTime())) return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
        return dStr;
      };
      const evD = formatResDate(ev.date || ev.eventDate);
      const sameDateResIds = evD ? RESERVATIONS.filter(r => formatResDate(r.date || r.eventDate) === evD && r.id !== ev.id).map(r => r.id) : [];
      
      const { data } = await window.supabaseClient
        .from('allocation_history')
        .select('asset_id,allocated_qty,reservation_id,allocation_batch,is_rental,recorded_at')
        .in('reservation_id', [ev.id, ...sameDateResIds]);
        
      if (data) {
        otherAllocs = data.filter(r => r.reservation_id !== ev.id && !r.is_rental);
        
        const thisData = data.filter(r => r.reservation_id === ev.id);
        if (thisData.length > 0) {
            const latest = thisData.reduce((prev, curr) => (new Date(curr.recorded_at).getTime() > new Date(prev.recorded_at).getTime()) ? curr : prev);
            latestBatchName = latest.allocation_batch;
            thisAlloc = thisData.filter(r => r.allocation_batch === latestBatchName);
        }
      }
    } catch(e) { console.warn('Failed to fetch allocs for manifest:', e); }
  }
  
  // Package Modification Detection
  const expectedBatchName = _genBatchName(ev);
  const dismissKey = `dismiss_mod_${ev.id}_${latestBatchName}_${expectedBatchName}`;
  const isDismissed = localStorage.getItem(dismissKey) === 'true';
  const isPackageModified = !isDismissed && latestBatchName && expectedBatchName && latestBatchName !== expectedBatchName;
  
  const isVenueModified = localStorage.getItem('venue_mod_' + ev.id) === 'true';
  let changeStr = '';
  
  let bannerTitle = '';
  let bannerText = '';
  let showBanner = false;

  if (isVenueModified) {
    showBanner = true;
    bannerTitle = 'Venue Equipment Modified';
    bannerText = 'Venue provided equipment were modified, please reallocate the deployment manifest to update allocation';
  } else if (isPackageModified) {
    showBanner = true;
    bannerTitle = 'Package Modified';
    bannerText = _getBatchModificationString(latestBatchName, expectedBatchName);
  }

  let modBanner = document.getElementById('alloc-modification-banner');
  if (!modBanner) {
    modBanner = document.createElement('div');
    modBanner.id = 'alloc-modification-banner';
    const panel = document.getElementById('alloc-manifest-panel');
    if (panel) panel.insertBefore(modBanner, panel.firstChild);
  }
  
  if (showBanner) {
    modBanner.innerHTML = `<div style="padding:14px 20px;background:rgba(196,154,60,0.12);border:1px solid var(--gold);border-radius:12px;display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:16px;">
      <div style="display:flex;align-items:center;gap:14px;">
        <div><div style="font-size:14px;font-weight:700;color:var(--gold);">${bannerTitle}</div>
        <div style="font-size:12px;color:var(--text-dim);">${bannerText}</div></div>
      </div>
      <div style="display:flex;align-items:center;gap:10px;">
        <button class="btn-primary" style="white-space:nowrap;flex-shrink:0;" onclick="autoAssignEquipmentFromManifest()">Reallocate</button>
        <button style="background:transparent;border:none;color:var(--text-dim);font-size:20px;cursor:pointer;padding:0;margin:0;line-height:1;" onclick="localStorage.setItem('${dismissKey}', 'true'); localStorage.removeItem('venue_mod_${ev.id}'); this.parentElement.parentElement.style.display='none';">&times;</button>
      </div>
    </div>`;
    modBanner.style.display = 'block';
  } else {
    modBanner.style.display = 'none';
  }
  // -----------------------------------------------------------------------------------

  let menuItemCount = 1;
  if (ev.packageItems && typeof CAT !== 'undefined') {
     menuItemCount = ev.packageItems.map(n => CAT.find(c => c.name === (typeof n === 'string' ? n : n.name))).filter(i => i && i.cat === 'food').length || 1;
  }

  const gv = id => Math.max(0, parseInt((document.getElementById(id) || {}).value || '0') || 0);
  const vdMap = {
    'venue-tables': gv('venue-tables'),
    'venue-chairs': gv('venue-chairs'),
    'venue-chafing': gv('venue-chafing'),
    'venue-dispensers': gv('venue-dispensers'),
    'venue-plates': gv('venue-plates'),
    'venue-forks': gv('venue-forks'),
    'venue-spoons': gv('venue-spoons'),
    'venue-knives': gv('venue-knives'),
    'venue-glasses': gv('venue-glasses'),
  };

  const cpe = ev.customerProvidedEquip || {};
  const cpeMap = {
    'venue-tables': cpe.tables || 0,
    'venue-chairs': cpe.chairs || 0,
    'venue-chafing': cpe.chafing || 0,
    'venue-dispensers': cpe.dispensers || 0,
    'venue-plates': cpe.plates || 0,
    'venue-forks': cpe.forks || 0,
    'venue-spoons': cpe.spoons || 0,
    'venue-knives': cpe.knives || 0,
    'venue-glasses': cpe.glasses || 0,
  };

  const bufF = (parseFloat((document.getElementById('alloc-buffer-fragile') || {}).value || '15') || 15) / 100;
  const bufS = (parseFloat((document.getElementById('alloc-buffer-sturdy') || {}).value || '10') || 10) / 100;
  const tablesNeeded = Math.ceil(pax / 8);
  const manifest = [];
  const shortages = [];
  _lastGeneratedManifest = []; // Reset

  if (ev.equipmentManifest && ev.equipmentManifest.length > 0) {
    // If a manifest was already saved, load it so we don't lose manually added/inferred items
    // (but update the inStock counts dynamically so they stay accurate to Supabase)
    ev.equipmentManifest.forEach(saved => {
      let asset = window.findAssetForRule({ assetId: saved.assetId }) || window.findAssetForRule({ name: saved.name });
      
      const baseStockQty = asset ? (parseInt(asset.quantity) || 0) : saved.inStock;
      const allocatedToOthers = asset ? otherAllocs.filter(r => (r.asset_id || '').toUpperCase() === (asset.asset_id || asset.id || '').toUpperCase()).reduce((s, r) => s + (parseInt(r.allocated_qty) || 0), 0) : 0;
      const stockQty = Math.max(0, baseStockQty - allocatedToOthers);
      
      const unavail = asset && (asset.status === 'Under Repair' || asset.status === 'Retired' || asset.status === 'under_repair' || asset.status === 'retired');
      const shortfall = Math.max(0, saved.finalReq - stockQty);
      const isFragile = !!(asset && asset.isFragile || (saved.name || '').toLowerCase().includes('plate') || (saved.name || '').toLowerCase().includes('glass') || (saved.name || '').toLowerCase().includes('cup'));
      
      const savedAlloc = thisAlloc.find(a => (a.asset_id || '').toUpperCase() === (asset ? (asset.asset_id || asset.id || '') : saved.assetId).toUpperCase() && !a.is_rental);
      const isLegacyAlloc = asset && asset.allocated_reservation_id === ev.id;
      const legacyAllocQty = isLegacyAlloc ? parseInt(asset.allocatedQty || asset.allocated_qty) || 0 : 0;
      
      const hasAlloc = !!savedAlloc || isLegacyAlloc;
      const finalAllocQty = savedAlloc ? savedAlloc.allocated_qty : (isLegacyAlloc ? legacyAllocQty : saved.finalReq);
      
      manifest.push({
        ...saved,
        inStock: stockQty,
        allocatedQty: finalAllocQty,
        hasSavedAlloc: hasAlloc,
        shortfall: shortfall,
        sufficient: shortfall <= 0,
        isFragile: isFragile,
        unavail: unavail
      });
    });
  } else if (ev.packageItems && ev.packageItems.length) {
    // Generate from scratch based on package items
    ev.packageItems.forEach(itemStr => {
      const ruleName = typeof itemStr === 'string' ? itemStr : (itemStr.name || 'Unknown');
      let asset = window.findAssetForRule({ name: ruleName });
      
      if (asset) {
        let exact = 1;
        const rule = (asset.allocationRule || 'fixed').toLowerCase();
        if (rule === 'per_pax') exact = pax;
        else if (rule === 'per_5_pax') exact = Math.ceil(pax / 5);
        else if (rule === 'per_8_pax') exact = Math.ceil(pax / 8);
        else if (rule === 'per_10_pax') exact = Math.ceil(pax / 10);
        else if (rule === 'per_table') exact = tablesNeeded;
        else if (rule === 'per_menu_item') exact = menuItemCount;

        let existing = manifest.find(m => m.assetId === (asset.asset_id || asset.id));
        if (!existing) {
          // Use total_qty (asset.quantity) as the authoritative stock count — matches Supabase directly.
          // Subtract quantities allocated to other reservations on the same date.
          const baseStockQty = parseInt(asset.quantity) || 0;
          const allocatedToOthers = otherAllocs.filter(r => (r.asset_id || '').toUpperCase() === (asset.asset_id || asset.id || '').toUpperCase()).reduce((s, r) => s + (parseInt(r.allocated_qty) || 0), 0);
          const stockQty = Math.max(0, baseStockQty - allocatedToOthers);
          
          const unavail = asset && (asset.status === 'Under Repair' || asset.status === 'Retired' || asset.status === 'under_repair' || asset.status === 'retired');
          
          let venueProv = 0;
          const lowName = asset.name.toLowerCase();
          const category = (asset.category || '').toLowerCase();
          if (lowName.includes('table') && category.includes('furniture')) venueProv = (vdMap['venue-tables'] || 0) + (cpeMap['venue-tables'] || 0);
          else if (lowName.includes('chair')) venueProv = (vdMap['venue-chairs'] || 0) + (cpeMap['venue-chairs'] || 0);
          else if (lowName.includes('plate')) venueProv = (vdMap['venue-plates'] || 0) + (cpeMap['venue-plates'] || 0);
          else if (lowName.includes('fork')) venueProv = (vdMap['venue-forks'] || 0) + (cpeMap['venue-forks'] || 0);
          else if (lowName.includes('spoon')) venueProv = (vdMap['venue-spoons'] || 0) + (cpeMap['venue-spoons'] || 0);
          else if (lowName.includes('kniv') || lowName.includes('knife')) venueProv = (vdMap['venue-knives'] || 0) + (cpeMap['venue-knives'] || 0);
          else if (lowName.includes('glass') || lowName.includes('goblet')) venueProv = (vdMap['venue-glasses'] || 0) + (cpeMap['venue-glasses'] || 0);
          else if (lowName.includes('chafing')) venueProv = (vdMap['venue-chafing'] || 0) + (cpeMap['venue-chafing'] || 0);
          else if (lowName.includes('dispenser')) venueProv = (vdMap['venue-dispensers'] || 0) + (cpeMap['venue-dispensers'] || 0);

          venueProv = Math.min(venueProv, exact);
          let afterVenue = Math.max(0, exact - venueProv);
          
          let buffer = 0;
          if (asset.isFragile || lowName.includes('plate') || lowName.includes('glass') || lowName.includes('cup')) {
             buffer = Math.ceil(afterVenue * bufF);
          } else if (exact >= 50) {
             buffer = Math.ceil(afterVenue * bufS);
          }
          
          const finalReq = afterVenue + buffer;
          const shortfall = Math.max(0, finalReq - stockQty);
          const isFragile = !!(asset.isFragile || lowName.includes('plate') || lowName.includes('glass') || lowName.includes('cup'));

          const savedAlloc = thisAlloc.find(a => (a.asset_id || '').toUpperCase() === (asset.asset_id || asset.id || '').toUpperCase() && !a.is_rental);

          if (finalReq > 0) {
            manifest.push({
              assetId: asset.asset_id || asset.id,
              name: asset.name,
              category: asset.category,
              ruleDesc: rule,
              exactReq: exact,
              venueProv: venueProv,
              afterVenue: afterVenue,
              buffer: buffer,
              finalReq: finalReq,
              inStock: stockQty,
              allocatedQty: savedAlloc ? savedAlloc.allocated_qty : finalReq,
              hasSavedAlloc: !!savedAlloc,
              shortfall: shortfall,
              sufficient: shortfall <= 0,
              isFragile: isFragile,
              unavail: unavail
            });
          }
        } else {
          existing.exactReq += exact;
          existing.finalReq += exact;
          existing.shortfall = Math.max(0, existing.finalReq - existing.inStock);
          existing.sufficient = existing.shortfall <= 0;
        }
      }
    });
  }

  const tbody = document.getElementById('alloc-manifest-tbody');
  if (tbody) {
    tbody.innerHTML = manifest.map(line => {
      const okCls = line.unavail ? 'critical' : (line.sufficient ? 'confirmed' : 'critical');
      const okLbl = line.unavail ? 'Unavailable' : (line.sufficient ? 'Covered' : `Short ${line.shortfall}`);
      const dqClr = line.sufficient ? 'var(--cream)' : 'var(--red)';
      return `<tr>
        <td><code style="font-size:11px;color:var(--gold);">${line.assetId}</code></td>
        <td><div class="item-name">${line.name}</div><div class="item-cat">${line.isFragile ? 'Fragile' : 'Sturdy'} \u00b7 ${line.note || ''}</div></td>
        <td><span class="badge pending" style="font-size:10px;">${line.category}</span></td>
        <td style="font-size:13px;font-weight:600;">${line.exactReq}</td>
        <td style="font-size:12px;color:var(--amber);">+${line.buffer}</td>
        <td style="font-size:14px;font-weight:700;color:${dqClr};">${line.exactReq + line.buffer}</td>
        <td style="font-size:13px;color:${line.inStock < line.finalReq ? 'var(--red)' : 'var(--text)'};">${line.inStock}</td>
        <td style="font-size:13px;color:var(--amber);">${line.venueProv > 0 ? line.venueProv : '\u2014'}</td>
        <td style="font-size:14px;font-weight:700;color:${dqClr};">${line.hasSavedAlloc ? line.allocatedQty : line.finalReq}</td>
        <td style="font-size:13px;font-weight:700;color:var(--gold);">${line.rentalQty > 0 ? line.rentalQty : '\u2014'}</td>
        <td><span class="badge ${okCls}" style="font-size:10px;white-space:nowrap;">${okLbl}</span></td>
      </tr>`;
    }).join('');
  }

  const okCount = manifest.filter(l => l.shortfall <= 0 && !l.unavail).length;
  const shortCount = manifest.filter(l => l.shortfall > 0 || l.unavail).length;
  const venueCount = manifest.filter(l => l.venueProv > 0).length;
  const st = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
  st('alloc-sum-items', manifest.length);
  st('alloc-sum-ok', okCount);
  st('alloc-sum-short', shortCount);
  st('alloc-sum-venue', venueCount);

  const badge = document.getElementById('alloc-manifest-badge');
  if (badge) {
    badge.textContent = shortCount > 0
      ? `${shortCount} SHORTAGE${shortCount > 1 ? 'S' : ''}`
      : 'FULLY COVERED';
    badge.className = '';
    badge.style.cssText = 'font-size:11px; font-weight:800; color:var(--gold); text-transform:uppercase; letter-spacing:1px;';
  }
  const sub = document.getElementById('alloc-manifest-sub');
  if (sub) sub.textContent = `${ev.client} \u2014 ${ev.date} \u00b7 ${pax} pax \u00b7 ${manifest.length} equipment lines`;

  const stbody = document.getElementById('alloc-shortage-tbody');
  if (stbody) {
    stbody.innerHTML = manifest.filter(l => l.shortfall > 0 || l.unavail).map(line => `<tr>
      <td><div class="item-name">${line.name}</div><div class="item-cat">${line.note || ''}</div></td>
      <td><span class="badge pending" style="font-size:10px;">${line.category}</span></td>
      <td style="font-size:13px;font-weight:700;">${line.finalReq}${line.unavail ? ' <span style="color:var(--red);font-size:10px;">(unavailable)</span>' : ''}</td>
      <td style="font-size:13px;color:var(--red);">${line.inStock}</td>
      <td style="font-size:14px;font-weight:700;color:var(--red);">${line.unavail ? 'All' : line.shortfall}</td>
      <td><button class="btn-reject" style="font-size:11px;" onclick="switchEqCycleTab('rentals', document.getElementById('eqc-tab-rentals'))">Go to Rental Hub</button></td>
    </tr>`).join('');
  }

  const banner = document.getElementById('alloc-status-banner');
  if (banner) {
    if (shortCount === 0) {
      banner.innerHTML = `<div style="padding:14px 20px;background:rgba(45,138,78,0.12);border:1px solid var(--green);border-radius:12px;display:flex;align-items:center;gap:14px;margin-bottom:4px;">
        <div><div style="font-size:14px;font-weight:700;color:var(--green);">All Equipment Fully Covered</div>
        <div style="font-size:12px;color:var(--text-dim);">Inventory satisfies all requirements including the safety buffer. Ready to deploy.</div></div></div>`;
    } else {
      banner.innerHTML = `<div style="padding:14px 20px;background:rgba(220,38,38,0.10);border:1px solid var(--red);border-radius:12px;display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:4px;">
        <div style="display:flex;align-items:center;gap:14px;">
          <div><div style="font-size:14px;font-weight:700;color:var(--red);">${shortCount} Equipment Line${shortCount > 1 ? 's' : ''} Cannot Be Fully Covered</div>
          <div style="font-size:12px;color:var(--text-dim);">Rent the missing items to ensure full deployment for ${pax} guests.</div></div>
        </div>
        <button class="btn-reject" style="white-space:nowrap;flex-shrink:0;" onclick="switchEqCycleTab('rentals', document.getElementById('eqc-tab-rentals'))">Go to Rental Equipment Hub</button>
      </div>`;
    }
    banner.style.display = 'block';
  }

  const show = (id, v) => { const el = document.getElementById(id); if (el) el.style.display = v ? 'block' : 'none'; };
  show('alloc-empty-state', false);
  show('alloc-manifest-panel', true);
  show('alloc-shortage-panel', shortCount > 0);

  // Store manifest for allocation buttons
  _lastGeneratedManifest = manifest.slice();
  
  // Apply any rental quantities that might already be confirmed for this reservation
  await checkAndApplyRentalQty(ev.id);

  // Update allocation button states based on current Supabase data
  updateAllocButtons();
}

// Print / export manifest
function printAllocationManifest() {
  if (!currentAllocEvent) return;
  const ev = currentAllocEvent;
  const tbl = document.getElementById('alloc-manifest-table');
  if (!tbl) return;
  const html = `<!DOCTYPE html><html><head><title>Deployment Manifest \u2014 ${ev.client}</title>
  <style>body{font-family:Arial,sans-serif;font-size:12px;color:#111;padding:20px;}h1{font-size:18px;margin-bottom:4px;}p{color:#555;margin-bottom:16px;}
  table{border-collapse:collapse;width:100%;}th{background:#1a1007;color:#c49a3c;padding:8px 10px;text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.5px;}
  td{padding:7px 10px;border-bottom:1px solid #ddd;font-size:12px;}</style></head><body>
  <h1>Deployment Manifest \u2014 ${ev.client}</h1>
  <p>${ev.date} \u00b7 ${ev.pax} pax \u00b7 ${ev.type} \u00b7 Generated: ${new Date().toLocaleString()}</p>
  ${tbl.outerHTML}
  <script>window.print();<\/script></body></html>`;
  const win = window.open('', '_blank');
  win.document.write(html);
  win.document.close();
}

// ====================================================================
// ALLOCATION MODE — module-level state
// ====================================================================
let _lastGeneratedManifest = []; // set by generateAllocationManifest
let _allocMode = null;           // null | 'auto' | 'manual' | 'modify'

// Parse differences between two batch names for the banner
function _getBatchModificationString(latestBatchName, expectedBatchName) {
  if (!latestBatchName || !expectedBatchName || latestBatchName === expectedBatchName) return '';
  
  const isLegacy = !latestBatchName.startsWith('BATCH-');
  if (isLegacy) return 'Legacy allocation detected. Please review and re-allocate to sync with new format.';

  let changes = [];
  
  const latestPaxMatch = latestBatchName.match(/-P(\d+)/);
  const expectedPaxMatch = expectedBatchName.match(/-P(\d+)/);
  if (latestPaxMatch && expectedPaxMatch && latestPaxMatch[1] !== expectedPaxMatch[1]) {
    const pOld = parseInt(latestPaxMatch[1]);
    const pNew = parseInt(expectedPaxMatch[1]);
    changes.push(`Pax ${pNew > pOld ? 'increased' : 'decreased'} from ${pOld} to ${pNew}`);
  }
  
  const getPkg = (batch) => {
    const pMatch = batch.match(/-P\d+-([^-]+)/);
    return pMatch ? pMatch[1] : null;
  };
  const latestPkg = getPkg(latestBatchName);
  const expectedPkg = getPkg(expectedBatchName);
  if (latestPkg && expectedPkg && latestPkg !== expectedPkg) {
    changes.push(`Package type modified`);
  }
  
  const latestItemsMatch = latestBatchName.match(/-I([A-Z0-9]+)$/);
  const expectedItemsMatch = expectedBatchName.match(/-I([A-Z0-9]+)$/);
  if (latestItemsMatch && expectedItemsMatch && latestItemsMatch[1] !== expectedItemsMatch[1]) {
    changes.push(`Package items added or removed`);
  } else if (!latestItemsMatch && expectedItemsMatch) {
    changes.push(`Package items modified`);
  }

  if (changes.length > 0) {
    return 'Detected changes: ' + changes.join(', ') + '. Please review and re-allocate.';
  }
  
  return 'The reservation requirements have changed since the last allocation. Please review and re-allocate.';
}

// Generate a batch name from reservation client name + event date
function _genBatchName(ev) {
  const initials = (ev.client || ev.name || 'EVT')
    .split(/\s+/).map(w => w[0] || '').join('').toUpperCase().slice(0, 4);
  const datePart = (ev.date || '').replace(/-/g, '');
  const resShort = (ev.id || '').replace(/-/g, '').slice(0, 6).toUpperCase();
  const pax = parseInt(ev.pax || ev.guests) || 0;
  const pkgName = (ev.packageName || 'CUST').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 10);
  
  const items = ev.packageItems || [];
  const itemsStr = items.map(i => typeof i === 'string' ? i : (i.name || '')).sort().join('|');
  let hash = 5381;
  for (let i = 0; i < itemsStr.length; i++) {
    hash = (hash * 33) ^ itemsStr.charCodeAt(i);
  }
  const itemsHash = Math.abs(hash).toString(16).toUpperCase();
  
  return `BATCH-${initials}-${datePart}-${resShort}-P${pax}-${pkgName}-I${itemsHash}`;
}

// Re-render the manifest tbody — optionally with an allocation qty column
function _renderManifestWithAllocCol(mode) {
  const manifest = _lastGeneratedManifest;
  const tbody = document.getElementById('alloc-manifest-tbody');
  const thead = document.querySelector('#alloc-manifest-table thead tr');
  if (!tbody || !thead) return;

  // Add or remove the Allocate Qty th
  const existingAllocTh = document.getElementById('alloc-th-qty');
  if (mode && !existingAllocTh) {
    const th = document.createElement('th');
    th.id = 'alloc-th-qty';
    th.textContent = 'Qty to Allocate';
    thead.appendChild(th);
  } else if (!mode && existingAllocTh) {
    existingAllocTh.remove();
  }

  tbody.innerHTML = manifest.map((line, idx) => {
    const okCls = line.unavail ? 'critical' : (line.shortfall <= 0 ? 'confirmed' : 'critical');
    const okLbl = line.unavail ? 'Unavailable' : (line.shortfall <= 0 ? 'Covered' : `Short ${line.shortfall}`);
    const dqClr = line.shortfall <= 0 ? 'var(--cream)' : 'var(--red)';

    // Determine prefilled value for allocation input
    let prefill = '';
    if (mode === 'auto') {
      prefill = Math.min(Math.max(0, line.finalReq - (line.rentalQty || 0)), line.inStock);
    }
    else if (mode === 'modify') {
      prefill = line.hasSavedAlloc ? line.allocatedQty : line.finalReq;
    }

    const allocCell = mode
      ? `<td><input type="number" id="alloc-qty-input-${idx}" class="input-field" value="${prefill}" min="0" max="${line.inStock}" style="width:80px;padding:4px 8px;font-size:12px;" oninput="this.value=Math.min(this.value,${line.inStock})" /></td>`
      : '';

    return `<tr>
      <td><code style="font-size:11px;color:var(--gold);">${line.assetId}</code></td>
      <td><div class="item-name">${line.name}</div><div class="item-cat">${line.isFragile ? 'Fragile' : 'Sturdy'} \u00b7 ${line.note || ''}</div></td>
      <td><span class="badge pending" style="font-size:10px;">${line.category}</span></td>
      <td style="font-size:13px;font-weight:600;">${line.exactReq}</td>
      <td style="font-size:12px;color:var(--amber);">+${line.buffer}</td>
      <td style="font-size:14px;font-weight:700;color:${dqClr};">${line.exactReq + line.buffer}</td>
      <td style="font-size:13px;color:${line.inStock < line.finalReq ? 'var(--red)' : 'var(--text)'};">${ line.inStock}</td>
      <td style="font-size:13px;color:var(--amber);">${line.venueProv > 0 ? line.venueProv : '\u2014'}</td>
      <td style="font-size:14px;font-weight:700;color:${dqClr};">${line.hasSavedAlloc ? line.allocatedQty : line.finalReq}</td>
      <td style="font-size:13px;font-weight:700;color:var(--gold);">${line.rentalQty > 0 ? line.rentalQty : '\u2014'}</td>
      <td><span class="badge ${okCls}" style="font-size:10px;white-space:nowrap;">${okLbl}</span></td>
      ${allocCell}
    </tr>`;
  }).join('');
}

// Update button states based on current alloc data
function updateAllocButtons() {
  const ev = currentAllocEvent;
  const modifyBtn = document.getElementById('btn-alloc-modify');
  const saveBtn = document.getElementById('btn-alloc-save');
  const cancelBtn = document.getElementById('btn-alloc-cancel');
  if (!modifyBtn) return;

  // Check if any manifest item is allocated to THIS reservation
  let allocatedToThis = false;
  if (ev && _lastGeneratedManifest.length) {
    for (const line of _lastGeneratedManifest) {
      if (line.hasSavedAlloc) {
        allocatedToThis = true;
        break;
      }
    }
  }

  modifyBtn.disabled = !allocatedToThis;
  modifyBtn.style.opacity = allocatedToThis ? '1' : '0.4';
  modifyBtn.style.cursor = allocatedToThis ? 'pointer' : 'not-allowed';
  modifyBtn.title = allocatedToThis ? '' : 'No allocation exists for this reservation yet';
}

// Enter an allocation mode (auto / manual / modify)
function enterAllocMode(mode) {
  if (!_lastGeneratedManifest.length) { showToast('Generate the manifest first.', 'error'); return; }
  _allocMode = mode;
  _renderManifestWithAllocCol(mode);

  // Show/hide action row
  const saveBtn   = document.getElementById('btn-alloc-save');
  const cancelBtn = document.getElementById('btn-alloc-cancel');
  const autoBtn   = document.getElementById('btn-alloc-auto');
  const manBtn    = document.getElementById('btn-alloc-manual');
  const modBtn    = document.getElementById('btn-alloc-modify');
  if (saveBtn)   saveBtn.style.display = 'inline-flex';
  if (cancelBtn) cancelBtn.style.display = 'inline-flex';
  if (autoBtn)   autoBtn.style.display = 'none';
  if (manBtn)    manBtn.style.display = 'none';
  if (modBtn)    modBtn.style.display = 'none';
}

// Cancel allocation mode — restore table without the column
function cancelAllocMode() {
  window._abortAllocSave = true;
  _allocMode = null;
  if (_lastGeneratedManifest.length) _renderManifestWithAllocCol(null);
  const saveBtn   = document.getElementById('btn-alloc-save');
  const cancelBtn = document.getElementById('btn-alloc-cancel');
  const autoBtn   = document.getElementById('btn-alloc-auto');
  const manBtn    = document.getElementById('btn-alloc-manual');
  const modBtn    = document.getElementById('btn-alloc-modify');
  if (saveBtn) {
    saveBtn.style.display = 'none';
    saveBtn.textContent = 'Save Allocation';
    saveBtn.disabled = false;
  }
  if (cancelBtn) cancelBtn.style.display = 'none';
  if (autoBtn)   autoBtn.style.display = 'inline-flex';
  if (manBtn)    manBtn.style.display = 'inline-flex';
  if (modBtn)    modBtn.style.display = 'inline-flex';
}

// Save the allocation to Supabase
async function saveAllocAssignment() {
  const ev = currentAllocEvent;
  if (!ev || !_lastGeneratedManifest.length) return;
  const sb = window.supabaseClient;
  if (!sb) { showToast('Supabase not available.', 'error'); return; }

  // Block if there are still unresolved shortages after rentals
  const remainingShort = _lastGeneratedManifest.filter(l => l.shortfall > 0 || l.unavail);
  if (remainingShort.length > 0) {
    showToast(`Cannot save: ${remainingShort.length} equipment line${remainingShort.length > 1 ? 's are' : ' is'} still short. Resolve via the Rental Equipment Hub first.`, 'error');
    return;
  }

  const batchName = _genBatchName(ev);
  const evLabel   = ev.packageName || ev.client || ev.name || ev.id;
  const saveBtn   = document.getElementById('btn-alloc-save');
  const cancelBtn = document.getElementById('btn-alloc-cancel');
  if (saveBtn) { saveBtn.textContent = 'Saving...'; saveBtn.disabled = true; }
  if (cancelBtn) { cancelBtn.disabled = true; }

  // Check if save was aborted
  window._abortAllocSave = false;

  // Load existing rental order to check for decreased rentals later
  let existingRentalOrder = null;
  if (typeof _loadRentalOrderForRes === 'function') {
    existingRentalOrder = await _loadRentalOrderForRes(ev.id);
  }

  let anyError = false;
  // Clear existing entries in allocation_history for this reservation
  // before inserting fresh ones — prevents duplicate rows on re-save.
  try {
    await sb.from('allocation_history').delete().eq('reservation_id', ev.id);
  } catch (e) { console.warn('[AllocSave] Pre-save history clear failed:', e); }
  try {
    for (let idx = 0; idx < _lastGeneratedManifest.length; idx++) {
      if (window._abortAllocSave) throw new Error('aborted');
      const line  = _lastGeneratedManifest[idx];
      // Skip rental-only lines (no real inventory asset)
      if (line.rentalQty > 0 && line.inStock === 0) continue;
      const asset = window.findAssetForRule({ name: line.name, assetId: line.assetId });
      if (!asset || !asset.supabaseId) continue;

      const inputEl = document.getElementById(`alloc-qty-input-${idx}`);
      const qty = inputEl ? Math.min(parseInt(inputEl.value) || 0, line.inStock) : Math.min(line.finalReq, line.inStock);

      const { error } = await sb
        .from('equipment_inventory')
        .update({
          allocated_qty: qty,
          allocation_batch: batchName,
          allocated_to: evLabel,
          allocated_reservation_id: ev.id,
          allocation_date: ev.date || ev.eventDate || null
        })
        .eq('id', asset.supabaseId);

      if (error) {
        console.error('[AllocSave] Supabase update failed:', error);
        anyError = true;
      } else {
        // Update local EIM_ASSETS cache
        asset.allocatedQty   = qty;
        asset.allocationBatch = batchName;
        asset.allocatedTo    = evLabel;
        // Log to allocation_history (own inventory — not rental)
        try {
          const { error: histErr } = await sb.from('allocation_history').insert({
            equipment_id: asset.supabaseId,
            asset_id: asset.id,
            equipment_name: asset.name,
            allocation_batch: batchName,
            reservation_id: ev.id,
            reservation_name: evLabel,
            allocation_date: ev.date || ev.eventDate || null,
            allocated_qty: qty,
            is_rental: false
          });
          if (histErr) console.warn('[AllocHistory] Insert failed:', histErr);
        } catch (e) { console.warn('[AllocHistory] Insert failed:', e); }
      }

      if (line.venueProv > 0) {
        try {
          const asset = window.findAssetForRule(line);
          await sb.from('allocation_history').insert({
            equipment_id: asset ? asset.supabaseId : null,
            asset_id: asset ? (asset.asset_id || asset.id) : line.assetId,
            equipment_name: line.name,
            allocation_batch: 'VENUE-' + batchName,
            reservation_id: ev.id,
            reservation_name: evLabel,
            allocation_date: ev.date || ev.eventDate || null,
            allocated_qty: line.venueProv,
            is_rental: false
          });
        } catch (e) { console.warn('[AllocHistory] Venue Insert failed:', e); }
      }
    }

    // Save rental items to allocation_history with is_rental: true
    if (typeof saveRentalAllocItems === 'function') {
      await saveRentalAllocItems(ev, batchName);
    }

    if (anyError) {
      showToast('Some items failed to save. Check console.', 'error');
    } else {
      const modBanner = document.getElementById('alloc-modification-banner');
      if (modBanner) modBanner.style.display = 'none';
      
      // Clear venue_mod flag if it exists
      localStorage.removeItem('venue_mod_' + ev.id);

      let hasDecreasedRentals = false;
      if (existingRentalOrder && existingRentalOrder.items && existingRentalOrder.items.length > 0) {
        existingRentalOrder.items.forEach(rItem => {
          const asset = window.findAssetForRule({ name: rItem.name });
          const assetId = asset ? (asset.asset_id || asset.id) : null;
          const lineIdx = _lastGeneratedManifest.findIndex(l => (l.assetId === assetId) || (l.name === rItem.name));
          const manifestLine = _lastGeneratedManifest[lineIdx];
          
          if (manifestLine) {
            const inputEl = document.getElementById(`alloc-qty-input-${lineIdx}`);
            const qtyAllocated = inputEl ? Math.min(parseInt(inputEl.value) || 0, manifestLine.inStock) : Math.min(manifestLine.finalReq, manifestLine.inStock);
            const newShortfall = Math.max(0, manifestLine.finalReq - qtyAllocated);
            if (rItem.qty_needed > newShortfall) {
              hasDecreasedRentals = true;
            }
          }
        });
      }

      if (hasDecreasedRentals) {
        cancelAllocMode();
        updateAllocButtons();
        const decreaseModal = document.createElement('div');
        decreaseModal.innerHTML = `<div style="position:fixed;top:0;left:0;width:100vw;height:100vh;background:rgba(0,0,0,0.5);z-index:9999;display:flex;align-items:center;justify-content:center;">
          <div style="background:var(--bg-panel);padding:30px;border-radius:12px;text-align:center;max-width:400px;border:1px solid var(--border);">
            <h2 style="margin-bottom:10px;color:var(--text);">Rentals Needed Decreased</h2>
            <p style="color:var(--text-dim);font-size:14px;margin-bottom:20px;">The required equipment has decreased. Please review and update your existing rental orders.</p>
            <button class="btn-primary" onclick="this.parentElement.parentElement.remove(); switchEqCycleTab('rentals', document.getElementById('eqc-tab-rentals'));">Redirect to Rental Equipment Hub</button>
          </div>
        </div>`;
        document.body.appendChild(decreaseModal);
      } else {
        showToast(`Allocation saved! Batch: ${batchName}`);
        cancelAllocMode();
        updateAllocButtons();
      }
    }
  } catch (err) {
    if (err.message === 'aborted') {
      showToast('Save aborted.', 'warning');
    } else {
      console.error('[AllocSave] Unexpected error:', err);
      showToast('Save failed: ' + (err.message || 'Unknown error'), 'error');
    }
  } finally {
    // Always restore the button — no matter what threw
    const cancelBtn = document.getElementById('btn-alloc-cancel');
    if (saveBtn) { saveBtn.textContent = 'Save Allocation'; saveBtn.disabled = false; }
    if (cancelBtn) { cancelBtn.disabled = false; }
  }
}

// ====================================================================
// VENUE EQUIPMENT (SUPABASE MIGRATION)
// ====================================================================

async function loadVenueEquipment(eventId) {
  if (!window.supabaseClient) return;
  const sb = window.supabaseClient;
  const ai = document.getElementById('venue-autofill-status');
  if (ai) { ai.textContent = 'Loading...'; ai.style.display = 'inline-block'; ai.style.color = 'var(--text-dim)'; }
  
  const { data, error } = await sb
    .from('venue_equipment')
    .select('*')
    .eq('reservation_id', eventId)
    .single();

  if (error || !data) {
    if (ai) ai.style.display = 'none';
    return;
  }

  // Populate HTML inputs
  const m = {
    'venue-tables': data.tables,
    'venue-chairs': data.chairs,
    'venue-chafing': data.chafing,
    'venue-dispensers': data.dispensers,
    'venue-plates': data.plates,
    'venue-forks': data.forks,
    'venue-spoons': data.spoons,
    'venue-knives': data.knives,
    'venue-glasses': data.glasses,
    'venue-other': data.other
  };
  
  for (const [id, val] of Object.entries(m)) {
    const el = document.getElementById(id);
    if (el) el.value = val || (id === 'venue-other' ? '' : 0);
  }

  if (ai) { ai.textContent = 'Auto-filled from saved venue data ✓'; ai.style.color = 'var(--green)'; }
}

async function applyVenueEquipment() {
  if (!currentAllocEvent) return;
  const ev = currentAllocEvent;
  if (!window.supabaseClient) return;
  const sb = window.supabaseClient;

  const ai = document.getElementById('venue-autofill-status');
  if (ai) { ai.textContent = 'Saving...'; ai.style.display = 'inline-block'; ai.style.color = 'var(--text-dim)'; }

  const gv = id => parseInt((document.getElementById(id) || {}).value || '0') || 0;
  
  const payload = {
    reservation_id: ev.id,
    tables: gv('venue-tables'),
    chairs: gv('venue-chairs'),
    chafing: gv('venue-chafing'),
    dispensers: gv('venue-dispensers'),
    plates: gv('venue-plates'),
    forks: gv('venue-forks'),
    spoons: gv('venue-spoons'),
    knives: gv('venue-knives'),
    glasses: gv('venue-glasses'),
    other: (document.getElementById('venue-other') || {}).value || '',
    saved_at: new Date().toISOString()
  };

  const { error } = await sb.from('venue_equipment').upsert(payload, { onConflict: 'reservation_id' });

  if (error) {
    console.error('Venue Equipment save failed:', error);
    if (ai) { ai.textContent = 'Failed to save'; ai.style.color = 'var(--red)'; }
  } else {
    if (ai) { ai.textContent = 'Applied and saved ✓'; ai.style.color = 'var(--green)'; }
    localStorage.setItem('venue_mod_' + ev.id, 'true');
    // Automatically recalculate the manifest with the new venue amounts
    generateAllocationManifest();
  }
}

async function removeVenueEquipment() {
  if (!currentAllocEvent) return;
  const ev = currentAllocEvent;
  if (!window.supabaseClient) return;
  const sb = window.supabaseClient;

  const ai = document.getElementById('venue-autofill-status');
  if (ai) { ai.textContent = 'Removing...'; ai.style.display = 'inline-block'; ai.style.color = 'var(--text-dim)'; }

  // Clear inputs locally first for immediate feedback
  ['venue-tables', 'venue-chairs', 'venue-chafing', 'venue-dispensers',
    'venue-plates', 'venue-forks', 'venue-spoons', 'venue-knives', 'venue-glasses'].forEach(id => {
      const el = document.getElementById(id); if (el) el.value = 0;
    });
  const otherEl = document.getElementById('venue-other'); if (otherEl) otherEl.value = '';

  const { error } = await sb.from('venue_equipment').delete().eq('reservation_id', ev.id);

  if (error) {
    console.error('Venue Equipment delete failed:', error);
    if (ai) { ai.textContent = 'Failed to remove'; ai.style.color = 'var(--red)'; }
  } else {
    if (ai) { ai.textContent = 'Removed successfully ✓'; ai.style.color = 'var(--gold)'; }
    localStorage.setItem('venue_mod_' + ev.id, 'true');
    // Automatically recalculate the manifest with zeroed venue amounts
    generateAllocationManifest();
  }
}

window.applyVenueEquipment = applyVenueEquipment;
window.removeVenueEquipment = removeVenueEquipment;
window.loadVenueEquipment = loadVenueEquipment;

