// ==================== EQUIPMENT RESUPPLY (NEW) ====================

async function renderResupplySection() {
  const rsAlloc = document.getElementById('rs-allocations-container');
  const rsRec = document.getElementById('rs-recommendations-tbody');
  
  if(rsAlloc) rsAlloc.innerHTML = '<div style="text-align:center;padding:30px;color:var(--text-dim);font-size:13px;">Loading allocations...</div>';
  if(rsRec) rsRec.innerHTML = '<tr><td colspan="4" style="text-align:center;padding:30px;color:var(--text-dim);font-size:13px;">Loading recommendations...</td></tr>';
  
  const sb = window.supabaseClient;
  if(!sb) return;

  try {
    const [resEq, resHist] = await Promise.all([
      sb.from('equipment_inventory').select('*'),
      sb.from('allocation_history').select('*').not('allocation_batch', 'is', null)
    ]);
    
    const baseEq = resEq.data || [];
    let histData = resHist.data || [];

    const dedupMap = {};
    histData.forEach(h => {
      if (!h.reservation_id) return;
      const isVenue = h.allocation_batch && h.allocation_batch.startsWith('VENUE-');
      if(isVenue) return; // Only count standard event allocations
      const key = `${h.reservation_id}_${h.equipment_name || h.asset_id}`;
      const time = h.recorded_at ? new Date(h.recorded_at).getTime() : 0;
      if (!dedupMap[key] || time > dedupMap[key].time) {
        dedupMap[key] = { row: h, time };
      }
    });
    histData = Object.values(dedupMap).map(d => d.row);
    
    let resMap = {};
    histData.forEach(h => {
       if(!resMap[h.reservation_id]) resMap[h.reservation_id] = { name: h.reservation_name || h.reservation_id, allocations: [] };
       resMap[h.reservation_id].allocations.push(h);
    });

    let allocHTML = '<table class="inv-table"><thead><tr><th>Reservation</th><th>Equipment</th><th style="text-align:center;">Required</th><th style="text-align:center;">Stock</th><th>Status</th></tr></thead><tbody>';
    
    let totalAllocMap = {};
    
    Object.values(resMap).forEach(res => {
       res.allocations.forEach(a => {
          totalAllocMap[a.asset_id] = (totalAllocMap[a.asset_id] || 0) + a.allocated_qty;
          
          const eq = baseEq.find(e => e.asset_id === a.asset_id || e.id === a.asset_id);
          const stock = eq ? Math.max(0, (eq.total_qty || 0) - (eq.maintenance_qty || 0) - (eq.retired_qty || 0)) : 0;
          const statusHTML = (stock >= a.allocated_qty) ? '<span style="color:var(--green)">Fulfillable</span>' : '<span style="color:var(--red)">Short</span>';
          
          allocHTML += `<tr>
            <td>${res.name}</td>
            <td>${a.equipment_name || eq?.name || a.asset_id}</td>
            <td style="text-align:center;">${a.allocated_qty}</td>
            <td style="text-align:center;">${stock}</td>
            <td>${statusHTML}</td>
          </tr>`;
       });
    });
    
    if(Object.keys(resMap).length === 0) {
       allocHTML += '<tr><td colspan="5" style="text-align:center;padding:30px;color:var(--text-dim);font-size:13px;">No approved allocations found.</td></tr>';
    }
    allocHTML += '</tbody></table>';
    
    if(rsAlloc) rsAlloc.innerHTML = allocHTML;
    
    window.resupplyRecs = [];
    baseEq.forEach(eq => {
       const totalAlloc = totalAllocMap[eq.asset_id] || totalAllocMap[eq.id] || 0;
       const stock = Math.max(0, (eq.total_qty || 0) - (eq.maintenance_qty || 0) - (eq.retired_qty || 0));
       if (totalAlloc > stock) {
          window.resupplyRecs.push({
             id: eq.id,
             asset_id: eq.asset_id,
             name: eq.name,
             stock: stock,
             shortage: totalAlloc - stock
          });
       }
    });
    
    renderResupplyRecommendations();
    renderShoppingList();
  } catch(e) {
    console.error(e);
  }
}
window.renderResupplySection = renderResupplySection;

function renderResupplyRecommendations() {
  const tbody = document.getElementById('rs-recommendations-tbody');
  if(!tbody) return;
  
  if(!window.resupplyRecs || window.resupplyRecs.length === 0) {
     tbody.innerHTML = '<tr><td colspan="4" style="text-align:center;padding:30px;color:var(--text-dim);font-size:13px;">No shortages detected.</td></tr>';
     return;
  }
  
  let html = '';
  window.resupplyRecs.forEach((r, idx) => {
     html += `<tr>
        <td>${r.name} <div style="font-size:11px;color:var(--text-dim);">${r.asset_id}</div></td>
        <td style="text-align:center;">${r.stock}</td>
        <td style="text-align:center; color:var(--red); font-weight:bold;">${r.shortage}</td>
        <td style="text-align:right;" id="rs-rec-action-${idx}">
           <button class="btn-outline" style="padding:4px 10px; font-size:12px;" onclick="assignResupply(${idx})">Assign for resupply</button>
        </td>
     </tr>`;
  });
  tbody.innerHTML = html;
}
window.renderResupplyRecommendations = renderResupplyRecommendations;

function assignResupply(idx) {
  const actionTd = document.getElementById(`rs-rec-action-${idx}`);
  if(!actionTd) return;
  const rec = window.resupplyRecs[idx];
  
  actionTd.innerHTML = `
     <div style="display:flex; align-items:center; justify-content:flex-end; gap:8px;">
        <span style="font-size:12px; color:var(--text-dim);">To resupply quantity:</span>
        <input type="number" id="rs-assign-qty-${idx}" class="input-field" style="width:70px; padding:4px; font-size:12px;" value="${rec.shortage}" min="1" />
        <button class="btn-primary" style="padding:4px 10px; font-size:12px;" onclick="confirmResupplyAssign(${idx})">Confirm</button>
     </div>
  `;
}
window.assignResupply = assignResupply;

window.shoppingList = window.shoppingList || [];

function confirmResupplyAssign(idx) {
  const qtyInput = document.getElementById(`rs-assign-qty-${idx}`);
  const qty = parseInt(qtyInput.value) || 0;
  if(qty <= 0) { alert('Quantity must be greater than 0.'); return; }
  
  const rec = window.resupplyRecs[idx];
  
  const existing = window.shoppingList.find(s => s.id === rec.id);
  if (existing) {
     existing.qty += qty;
  } else {
     window.shoppingList.push({
        id: rec.id,
        asset_id: rec.asset_id,
        name: rec.name,
        qty: qty
     });
  }
  
  renderResupplyRecommendations();
  renderShoppingList();
}
window.confirmResupplyAssign = confirmResupplyAssign;

function renderShoppingList() {
  const tbody = document.getElementById('rs-shopping-tbody');
  if(!tbody) return;
  
  if(!window.shoppingList || window.shoppingList.length === 0) {
     tbody.innerHTML = '<tr><td colspan="2" style="text-align:center;padding:30px;color:var(--text-dim);font-size:13px;">No items assigned yet.</td></tr>';
     return;
  }
  
  let html = '';
  window.shoppingList.forEach(item => {
     html += `<tr>
        <td>${item.name} <div style="font-size:11px;color:var(--text-dim);">${item.asset_id}</div></td>
        <td style="text-align:right; font-weight:bold; color:var(--gold);">${item.qty}</td>
     </tr>`;
  });
  tbody.innerHTML = html;
}
window.renderShoppingList = renderShoppingList;

/* ===== EQUIPMENT MAINTENANCE PIPELINE (EIM 9)
   Functions: renderMaintenanceSection, switchMaintenanceTab,
   loadMaintenanceDataFromSupabase, updateMaintenanceStats, renderMaintenanceGrid,
   retireMaintenanceEquipment, sendToRepair, returnToService
   ==================================================================== */

window.maintenanceTasks = window.maintenanceTasks || [];
window.routineChecksCache = window.routineChecksCache || [];

async function loadMaintenanceDataFromSupabase() {
  try {
    const sb = window.supabaseClient;
    if (!sb) return;

    // Load active maintenance tasks
    const { data: mntData } = await sb.from('equipment_maintenance').select('*');
    if (mntData) {
      window.maintenanceTasks = mntData;
    }

    // Load routine checks to find reported dates
    const { data: rcData } = await sb.from('routine_check').select('*').eq('status', 'incident');
    if (rcData) {
      window.routineChecksCache = rcData;
    }

    if (document.getElementById('section-maintenance')?.classList.contains('active')) {
      renderMaintenanceSection();
    }
  } catch (e) {
    console.error('Error loading maintenance data:', e);
  }
}

function renderMaintenanceSection() {
  updateMaintenanceStats();
  renderMaintenanceGrid();
  renderMaintenanceHistory();
}
window.renderMaintenanceSection = renderMaintenanceSection;

function updateMaintenanceStats() {
  let reviewCount = 0;
  let repairCount = 0;
  let fixedCount = 0;
  
  (EIM_ASSETS || []).forEach(asset => {
    if (asset.maintenance_qty > 0) {
      let pendingQty = 0;
      const mntRecs = window.maintenanceTasks.filter(t => (t.equipment_id === asset.supabaseId || t.equipment_id === asset.id) && t.status === 'pending');
      mntRecs.forEach(r => pendingQty += (r.quantity || 1));
      
      let reviewQty = asset.maintenance_qty - pendingQty;
      if (reviewQty > 0) reviewCount += reviewQty;
    }
  });

  window.maintenanceTasks.forEach(t => {
    if (t.status === 'pending') repairCount += (t.quantity || 1);
    if (t.status === 'Repaired') fixedCount += (t.quantity || 1);
  });

  let retiredCount = (EIM_ASSETS || []).reduce((sum, a) => sum + (a.retired_qty || 0), 0);

  const elReview = document.getElementById('mnt-stat-review'); if (elReview) elReview.textContent = reviewCount;
  const elRepair = document.getElementById('mnt-stat-repair'); if (elRepair) elRepair.textContent = repairCount;
  const elFixed = document.getElementById('mnt-stat-fixed'); if (elFixed) elFixed.textContent = fixedCount;
  const elRetired = document.getElementById('mnt-stat-retired'); if (elRetired) elRetired.textContent = retiredCount;

  const badge = document.getElementById('mnt-sidebar-badge');
  if (badge) {
    const totalActive = reviewCount + repairCount;
    badge.style.display = totalActive > 0 ? '' : 'none';
    badge.textContent = totalActive;
  }
}

function isCurrentMonth(dateStr) {
  if (!dateStr) return false;
  const d = new Date(dateStr);
  const now = new Date();
  return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear();
}

function getReportedDateForAsset(assetId) {
  let latestDate = null;
  // Parse routine check incidents
  window.routineChecksCache.forEach(rc => {
    if (rc.incidents) {
      let incs = typeof rc.incidents === 'string' ? JSON.parse(rc.incidents) : rc.incidents;
      if (Array.isArray(incs)) {
        incs.forEach(inc => {
          if (inc.assetId === assetId || inc.equipment_id === assetId) {
            let d = new Date(rc.checked_at);
            if (!latestDate || d > latestDate) latestDate = d;
          }
        });
      }
    }
  });
  if (latestDate) {
    return latestDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) + ' - ' + latestDate.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
  }
  return 'Unknown';
}

