window.renderMaintenanceGrid = renderMaintenanceGrid;

async function retireMaintenanceEquipment(assetId, qty) {
  if (!confirm('Are you sure you want to retire ' + qty + ' of this equipment?')) return;
  
  try {
    const sb = window.supabaseClient;
    const asset = EIM_ASSETS.find(a => a.id === assetId);
    if (!asset) return;
    
    // Supabase ID logic
    const equipmentUuid = asset.supabaseId || asset.id;

    let newMntQty = Math.max(0, asset.maintenance_qty - qty);
    let newRetQty = (asset.retired_qty || 0) + qty;

    const { error } = await sb.from('equipment_inventory')
      .update({ maintenance_qty: newMntQty, retired_qty: newRetQty })
      .eq('id', equipmentUuid);

    if (error) throw error;
    
    // Insert into equipment_maintenance to log the retirement properly
    let newRec = {
      equipment_id: equipmentUuid,
      equipment_name: asset.name,
      quantity: qty,
      status: 'retired',
      source: 'Pipeline',
      repair_notes: 'Retired from active pipeline'
    };
    const { data: mntData, error: mntError } = await sb.from('equipment_maintenance').insert([newRec]).select().single();
    if (mntError) console.error('Failed to log retirement history:', mntError);
    
    asset.maintenance_qty = newMntQty;
    asset.retired_qty = newRetQty;
    showToast(' Equipment retired successfully.');
    
    // Log as retired in maintenanceTasks history for tracking
    if (mntData) {
      window.maintenanceTasks.push(mntData);
    } else {
      window.maintenanceTasks.push({
          id: 'MT-RET-' + Date.now(),
          equipment_id: equipmentUuid,
          equipment_name: asset.name,
          quantity: qty,
          status: 'retired',
          created_at: new Date().toISOString()
      });
    }

    renderMaintenanceSection();
  } catch (e) {
    console.error('Error retiring equipment:', e);
    alert('Failed to retire equipment. Check console.');
  }
}
window.retireMaintenanceEquipment = retireMaintenanceEquipment;

async function sendToRepair(assetId, maxQty) {
  const qtyInput = document.getElementById('repair-qty-' + assetId);
  if (!qtyInput) return;
  
  let qty = parseInt(qtyInput.value, 10);
  if (isNaN(qty) || qty <= 0 || qty > maxQty) {
    alert('Invalid quantity. Must be between 1 and ' + maxQty);
    return;
  }

  try {
    const sb = window.supabaseClient;
    const asset = EIM_ASSETS.find(a => a.id === assetId);
    if (!asset) return;
    
    // Supabase ID logic
    const equipmentUuid = asset.supabaseId || asset.id;

    // Check if pending record exists
    const mntRec = window.maintenanceTasks.find(t => t.equipment_id === equipmentUuid && t.status === 'pending');
    
    if (mntRec) {
      let newQty = (mntRec.quantity || 1) + qty;
      const { error } = await sb.from('equipment_maintenance')
        .update({ quantity: newQty })
        .eq('id', mntRec.id);
      if (error) throw error;
      mntRec.quantity = newQty;
    } else {
      let newRec = {
        equipment_id: equipmentUuid,
        equipment_name: asset.name,
        quantity: qty,
        status: 'pending',
        source: 'Routine Check',
        repair_notes: ''
      };
      const { data, error } = await sb.from('equipment_maintenance')
        .insert([newRec])
        .select()
        .single();
      if (error) throw error;
      window.maintenanceTasks.push(data);
    }
    
    showToast(' Sent to repair.');
    renderMaintenanceSection();
  } catch (e) {
    console.error('Error sending to repair:', e);
    alert('Failed to send to repair. Check console.');
  }
}
window.sendToRepair = sendToRepair;

async function returnToService(mntId, assetId, repairQty) {
  try {
    const noteEl = document.getElementById('repair-note-' + mntId);
    let note = noteEl ? noteEl.value.trim() : '';

    const sb = window.supabaseClient;
    const asset = EIM_ASSETS.find(a => a.id === assetId);
    if (!asset) return;
    
    // Supabase ID logic
    const equipmentUuid = asset.supabaseId || asset.id;

    // First update the maintenance task
    const { error: mntError } = await sb.from('equipment_maintenance')
      .update({ status: 'Repaired', repair_notes: note, date_out: new Date().toISOString() })
      .eq('id', mntId);
    
    if (mntError) throw mntError;

    // Then update equipment_inventory
    let newMntQty = Math.max(0, asset.maintenance_qty - repairQty);
    let newGoodQty = (asset.good_qty || 0) + repairQty;
    
    const { error: invError } = await sb.from('equipment_inventory')
      .update({ maintenance_qty: newMntQty, good_qty: newGoodQty })
      .eq('id', equipmentUuid);
      
    if (invError) throw invError;

    asset.maintenance_qty = newMntQty;
    asset.good_qty = newGoodQty;

    let localRec = window.maintenanceTasks.find(t => t.id === mntId);
    if (localRec) {
      localRec.status = 'Repaired';
      localRec.repair_notes = note;
      localRec.date_out = new Date().toISOString();
    }
    
    showToast(' Item returned to service.');
    renderMaintenanceSection();
  } catch (e) {
    console.error('Error returning to service:', e);
    alert('Failed to return to service. Check console.');
  }
}
window.returnToService = returnToService;

