    html += '<td style="font-weight:700;color:' + resColor + ';">' + resLabel + '</td>';
    html += '<td style="font-size:11px;color:var(--text-mid);">' + escHtml(t.repair_notes || t.issue || '') + '</td>';
    html += '<td style="font-size:11px;color:var(--text-mid);">' + (t.quantity || 1) + ' pcs</td>';
