window.triggerMeetingMode = async function () {
  if (typeof activeDetailsMtId === 'undefined' || !activeDetailsMtId) return;
  const mtId = activeDetailsMtId;

  // Signal live meeting for customer sync
  try {
    const { doc, updateDoc } = window.firebaseFns;
    await updateDoc(doc(window.firebaseDB, 'meetings', mtId), { status: 'live' });
  } catch (e) { console.error("Sync Error:", e); }

  closeMtDetailsModal();
  initiateMeetingMode(mtId);
};

window.markPaymentConfirmed = async function () {
  if (!activeMeetingResCache) return;
  const btn = event.target;
  btn.disabled = true;
  try {
    const { doc, updateDoc } = window.firebaseFns;
    await updateDoc(doc(window.firebaseDB, 'reservations', activeMeetingResCache.id), {
      paymentStatus: 'paid',
      paymentRequested: false
    });
    alert('Payment confirmed for reservation.');
  } catch (e) { alert('Update failed'); }
  finally { btn.disabled = false; }
};

window.requestPaymongoPayment = async function () {
  if (!activeMeetingResCache || !activeMeeting) return;
  if (activeMeeting.id === 'demo') return alert('Payment flow is disabled in demo mode.');

  const btn = document.getElementById('btn-pay-initial');
  if (!btn) return;
  btn.disabled = true;
  btn.textContent = 'Sending...';

  try {
    const sb = window.supabaseClient;
    if (!sb) throw new Error('Supabase not ready');

    const { error } = await sb.from('meetings').update({
      initial_fee_status: 'triggered'
    }).eq('id', activeMeeting.id);

    if (error) throw error;

    // Update button to reflect waiting state
    btn.textContent = 'Waiting for Customer...';
    btn.style.background = 'rgba(255,255,255,0.1)';
    btn.style.color = 'var(--text-dim)';

    const cancelBtn = document.getElementById('btn-cancel-pay-initial');
    if (cancelBtn) cancelBtn.style.display = 'flex';

    // Toast
    const toast = document.createElement('div');
    toast.style.cssText = 'position:fixed;bottom:24px;right:24px;background:var(--primary);color:#fff;padding:14px 20px;border-radius:10px;font-size:13px;font-weight:600;z-index:9999;box-shadow:0 4px 20px rgba(0,0,0,0.3);';
    toast.textContent = 'Payment panel sent to customer — awaiting their response.';
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 4000);

  } catch (e) {
    console.error('[requestPaymongoPayment]', e);
    alert('Failed to trigger payment panel: ' + e.message);
    btn.disabled = false;
    btn.textContent = 'Commence Initial Fee Payment';
  }
};

window.cancelInitialFeePayment = async function () {
  if (!activeMeeting) return;
  const btn = document.getElementById('btn-cancel-pay-initial');
  if (btn) {
    btn.disabled = true;
    btn.textContent = 'Canceling...';
  }

  try {
    const sb = window.supabaseClient;
    if (!sb) throw new Error('Supabase not ready');

    const updateObj = {
      initial_fee_status: null,
      initial_fee_deadline: null
    };

    const { error } = await sb.from('meetings').update(updateObj).eq('id', activeMeeting.id);
    if (error) throw error;

    if (activeMeeting.reservationId) {
      await sb.from('reservations').update(updateObj).eq('id', activeMeeting.reservationId);
    }

    if (window.firebaseFns && window.firebaseDB) {
      try {
        const { doc, updateDoc } = window.firebaseFns;
        await updateDoc(doc(window.firebaseDB, 'meetings', activeMeeting.id), updateObj);
      } catch(e) {}
    }

    // Update local state
    activeMeeting.initial_fee_status = null;
    activeMeeting.initial_fee_deadline = null;

    if (window.updateBillingUI) window.updateBillingUI(activeMeetingResCache);

    // Toast
    const toast = document.createElement('div');
    toast.style.cssText = 'position:fixed;bottom:24px;right:24px;background:#e23636;color:#fff;padding:14px 20px;border-radius:10px;font-size:13px;font-weight:600;z-index:9999;box-shadow:0 4px 20px rgba(0,0,0,0.3);';
    toast.textContent = 'Payment request cancelled.';
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 4000);

  } catch (e) {
    console.error('[cancelInitialFeePayment]', e);
    alert('Failed to cancel request: ' + e.message);
    if (btn) {
      btn.disabled = false;
      btn.textContent = 'Cancel Request';
    }
  }
};

window.postponeInitialFeeFromAdmin = async function() {
  if (!activeMeeting || !activeMeeting.id) return;
  const btn = document.getElementById('btn-customer-cant-pay');
  if (btn) { btn.disabled = true; btn.textContent = 'Updating...'; }

  try {
    const deadline = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
    const updateObj = {
      initial_fee_status: 'declined_24h',
      initial_fee_deadline: deadline
    };

    if (window.supabaseClient) {
      await window.supabaseClient.from('meetings').update(updateObj).eq('id', activeMeeting.id);
      if (activeMeeting.reservationId) {
        await window.supabaseClient.from('reservations').update(updateObj).eq('id', activeMeeting.reservationId);
      }
    }

    if (window.firebaseFns && window.firebaseDB) {
      try {
        const { doc, updateDoc } = window.firebaseFns;
        await updateDoc(doc(window.firebaseDB, 'meetings', activeMeeting.id), updateObj);
      } catch(e) {}
    }

    activeMeeting.initial_fee_status = 'declined_24h';
    activeMeeting.initial_fee_deadline = deadline;

    if (window.updateBillingUI) window.updateBillingUI(activeMeetingResCache);

    const toast = document.createElement('div');
    toast.style.cssText = 'position:fixed;bottom:24px;right:24px;background:#e67e22;color:#fff;padding:14px 20px;border-radius:10px;font-size:13px;font-weight:600;z-index:9999;box-shadow:0 4px 20px rgba(0,0,0,0.3);';
    toast.textContent = 'Triggered 24-hour initial fee deadline for customer.';
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 4000);

  } catch(e) {
    console.error('[postponeInitialFeeFromAdmin]', e);
    alert('Failed to update: ' + e.message);
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = "Customer can't pay right now"; }
  }
};
window.closePosAndCancel = function () {
  document.getElementById('admin-pos-modal').style.display = 'none';
  window.cancelInitialFeePayment();
};

window.openPosModal = function () {
  document.getElementById('pos-cash-received').value = '';
  document.getElementById('pos-change-display').innerHTML = '&#8369;0.00';
  document.getElementById('pos-error-msg').style.display = 'none';
  document.getElementById('btn-pos-confirm').disabled = true;
  document.getElementById('admin-pos-modal').style.display = 'flex';
  document.getElementById('pos-cash-received').focus();
};

window.calculatePosChange = function () {
  const amountDue = 5000;
  const cashInput = document.getElementById('pos-cash-received');
  const changeDisplay = document.getElementById('pos-change-display');
  const errorMsg = document.getElementById('pos-error-msg');
  const confirmBtn = document.getElementById('btn-pos-confirm');

  const cashReceived = parseFloat(cashInput.value);

  if (isNaN(cashReceived) || cashReceived < amountDue) {
    changeDisplay.innerHTML = '&#8369;0.00';
    errorMsg.style.display = 'block';
    confirmBtn.disabled = true;
  } else {
    const change = cashReceived - amountDue;
    changeDisplay.innerHTML = '&#8369;' + change.toLocaleString('en-US', { minimumFractionDigits: 2 });
    errorMsg.style.display = 'none';
    confirmBtn.disabled = false;
  }
};

window.processPosPayment = async function () {
  if (!activeMeetingResCache || !activeMeeting) return;
  const btn = document.getElementById('btn-pos-confirm');
  btn.disabled = true;
  btn.textContent = 'Processing...';

  try {
    const sb = window.supabaseClient;
    if (!sb) throw new Error('Supabase not ready');

    const cashReceived = parseFloat(document.getElementById('pos-cash-received').value);
    if (isNaN(cashReceived) || cashReceived < 5000) throw new Error('Invalid cash amount');
    const changeGiven = cashReceived - 5000;

    const loggedStr = sessionStorage.getItem('halden_admin');
    let adminName = 'Admin';
    if (loggedStr) {
      const parsed = JSON.parse(loggedStr);
      if (parsed.name) adminName = parsed.name;
    }

    const now = new Date().toISOString();
    const { error } = await sb.from('meetings').update({
      initial_fee_status: 'paid',
      initial_fee_method: 'cash',
      initial_fee_paid_at: now,
      initial_fee_received: cashReceived,
      initial_fee_change: changeGiven,
      initial_fee_received_by: adminName
    }).eq('id', activeMeeting.id);

    if (error) throw error;

    const { doc, updateDoc } = window.firebaseFns;
    await updateDoc(doc(window.firebaseDB, 'reservations', activeMeetingResCache.id), {
      paymentStatus: 'paid',
      paymentAmount: '5000',
      cashPaymentStatus: 'confirmed',
      initialFeeStatus: 'paid',
      initialFeeMethod: 'cash'
    });

    try {
      // Firebase handles the primary 'reservations' state, these columns don't exist in Supabase
      // await sb.from('reservations').update({ initialFeeStatus: 'paid', initialFeeMethod: 'cash' }).eq('id', activeMeetingResCache.id);
      await sb.from('reservation_payments').upsert({
        reservation_id: activeMeetingResCache.id,
        initial_fee_status: 'paid',
        initial_fee_method: 'cash',
        initial_fee_paid_at: now,
        initial_fee_received: cashReceived,
        initial_fee_change: changeGiven,
        initial_fee_received_by: adminName,
        updated_at: now
      }, { onConflict: 'reservation_id' });
    } catch (err) {
      console.warn('Failed to sync payments table:', err);
    }

    document.getElementById('admin-pos-modal').style.display = 'none';

    const toast = document.createElement('div');
    toast.style.cssText = 'position:fixed;bottom:24px;right:24px;background:#2e7d32;color:#fff;padding:14px 20px;border-radius:10px;font-size:13px;font-weight:600;z-index:9999;box-shadow:0 4px 20px rgba(0,0,0,0.3);';
    toast.textContent = 'POS Transaction Complete. Reservation fee settled.';
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 4000);

  } catch (e) {
    console.error('[processPosPayment]', e);
    alert('Failed to process payment: ' + e.message);
    btn.disabled = false;
    btn.textContent = 'Confirm Payment';
  }
};


